// ── Stage access rules ───────────────────────────────────────
// Returns effective permissions for the current user + lifecycle stage.
// bypass_roles always get the fully-open set regardless of rules.
function getStageRules(stage, userAuth) {
  const open = {
    editable: true, can_log_time: true, can_add_activities: true,
    can_comment: true, can_upload_docs: true,
    can_edit_activity_phase: true, can_edit_activity_predecessors: true,
    visible_tabs: null,
  };
  if (!stage?.rules) return open;
  const r = stage.rules;
  const bypass = r.bypass_roles ?? ["admin", "manager"];
  const isBypassed = bypass.some(role => {
    if (role === "admin")      return userAuth.isAdmin;
    if (role === "manager")    return userAuth.isManager;
    if (role === "consultant") return userAuth.isConsultant;
    if (role === "client")     return userAuth.isClient;
    return false;
  });
  if (isBypassed) return open;
  return {
    editable:                    r.editable                    ?? true,
    can_log_time:                r.can_log_time                ?? true,
    can_add_activities:          r.can_add_activities          ?? true,
    can_comment:                 r.can_comment                 ?? true,
    can_upload_docs:             r.can_upload_docs             ?? true,
    can_edit_activity_phase:     r.can_edit_activity_phase     ?? true,
    can_edit_activity_predecessors: r.can_edit_activity_predecessors ?? true,
    visible_tabs:                r.visible_tabs                ?? null,
  };
}

// ── Activity adherence helper ────────────────────────────────
function activityAdherence(act) {
  if (act.progress_pct === 100) return "complete";
  if (!act.end_date_plan) return null;
  const today = new Date().toISOString().slice(0, 10);
  if (today > act.end_date_plan) return "overdue";
  if (!act.start_date_plan) return "on_track";
  const total = (new Date(act.end_date_plan) - new Date(act.start_date_plan + "T00:00:00")) / 86400000;
  const elapsed = (Date.now() - new Date(act.start_date_plan + "T00:00:00")) / 86400000;
  const expected = total > 0 ? Math.round((elapsed / total) * 100) : 0;
  if (act.progress_pct >= expected - 10) return "on_track";
  if (act.progress_pct >= expected - 25) return "at_risk";
  return "behind";
}

function useCaseDocuments(caseId) {
  const [documents, setDocuments] = useState([]);
  const [loading, setLoading]     = useState(true);

  const fetchDocs = useCallback(async () => {
    if (!caseId) { setLoading(false); return; }
    const { data } = await supabase.from("case_documents")
      .select("*, uploader:uploaded_by(full_name)")
      .eq("case_id", caseId).order("created_at", { ascending: false });
    setDocuments(data ?? []);
    setLoading(false);
  }, [caseId]);

  useEffect(() => { fetchDocs(); }, [fetchDocs]);

  async function addDocument(file, notes = "") {
    const { data: { user } } = await supabase.auth.getUser();
    const path = `${caseId}/${Date.now()}-${file.name}`;
    const { error: uploadError } = await supabase.storage
      .from("case-documents").upload(path, file, { upsert: false });
    if (uploadError) throw uploadError;
    const { data: { publicUrl } } = supabase.storage.from("case-documents").getPublicUrl(path);
    const ext = file.name.split(".").pop();
    const { error } = await supabase.from("case_documents").insert({
      case_id: caseId, uploaded_by: user.id,
      file_name: file.name, file_url: publicUrl,
      file_type: file.type || ext,
      file_size_kb: Math.round(file.size / 1024),
      notes,
    });
    if (error) throw error;
    await fetchDocs();
    notifyCaseParticipants(caseId, user.id, "Document uploaded", `New document attached: "${file.name}"${notes ? ` — ${notes}` : ""}.`, { case_id: caseId, event_type: "document" });
    return publicUrl;
  }

  async function deleteDocument(id, fileUrl) {
    if (fileUrl) {
      const pathPart = fileUrl.split("/case-documents/")[1];
      if (pathPart) await supabase.storage.from("case-documents").remove([pathPart]);
    }
    await supabase.from("case_documents").delete().eq("id", id);
    await fetchDocs();
  }

  return { documents, loading, addDocument, deleteDocument, refetch: fetchDocs };
}

function useAuth() {
  const [user, setUser]       = useState(null);
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
      if (session?.user) fetchProfile(session.user.id);
      else setLoading(false);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (_, session) => {
      setUser(session?.user ?? null);
      if (session?.user) fetchProfile(session.user.id);
      else { setProfile(null); setLoading(false); }
    });
    return () => subscription.unsubscribe();
  }, []);

  async function fetchProfile(userId) {
    let { data } = await supabase
      .from("users")
      .select("*, consultant_profiles(*), client_profiles(*)")
      .eq("id", userId)
      .single();

    if (!data) {
      // Trigger may have failed — try creating the public.users row client-side
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        const meta = user.user_metadata ?? {};
        await supabase.from("users").insert({
          id: user.id,
          email: user.email,
          full_name: meta.full_name || user.email.split("@")[0],
          role: meta.role || "consultant",
        });
        const { data: retry } = await supabase
          .from("users")
          .select("*, consultant_profiles(*), client_profiles(*)")
          .eq("id", userId)
          .single();
        data = retry;
      }
    }

    setProfile(data ?? null);
    setLoading(false);
  }

  async function signIn(email, password) {
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) throw error;
    return data;
  }

  async function signUp(email, password, fullName, role = "consultant") {
    const { data, error } = await supabase.auth.signUp({
      email, password,
      options: { data: { full_name: fullName, role } }
    });
    if (error) throw error;
    logEvent('user.signed_up', { userId: data.user?.id, userEmail: email, entityType: 'user', entityName: fullName, metadata: { role } });
    return data;
  }

  async function signOut() {
    await supabase.auth.signOut();
  }

  return {
    user, profile, loading,
    role: profile?.role ?? null,
    signIn, signUp, signOut,
    isAdmin:      profile?.role === "admin",
    isManager:    profile?.role === "manager",
    isConsultant: profile?.role === "consultant",
    isClient:     profile?.role === "client",
    isKeyUser:    profile?.role === "key_user",
    isHeadhunter: profile?.role === "headhunter",
    isFinalUser:  profile?.role === "final_user",
  };
}

function useCases(filters = {}) {
  const [cases, setCases]     = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState(null);
  const filterKey = JSON.stringify(filters);

  const fetchCases = useCallback(async () => {
    setLoading(true);
    let query = supabase
      .from("cases")
      .select(`
        *,
        client:client_id(id, full_name, email, avatar_url, client_profiles(company_name)),
        manager:manager_id(id, full_name, email, avatar_url),
        case_assignments(consultant_id, time_commitment,
          users:consultant_id(id, full_name, avatar_url)),
        case_key_users(user_id, area, users:user_id(full_name, email)),
        applications(count),
        project:project_id(id, name, avatar_url, client:client_id(id, avatar_url))
      `)
      .order("created_at", { ascending: false });

    if (filters.status)    query = query.eq("status", filters.status);
    if (filters.priority)  query = query.eq("priority", filters.priority);
    if (filters.search)    query = query.ilike("title", `%${filters.search}%`);
    if (filters.client_id) query = query.eq("client_id", filters.client_id);

    const { data, error } = await query;
    if (error) setError(error.message);
    else setCases(data ?? []);
    setLoading(false);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filterKey]);

  useEffect(() => { fetchCases(); }, [fetchCases]);

  useEffect(() => {
    const channel = supabase.channel("cases-rt")
      .on("postgres_changes", { event: "*", schema: "public", table: "cases" }, fetchCases)
      .subscribe();
    return () => supabase.removeChannel(channel);
  }, [fetchCases]);

  async function createCase(data) {
    const { data: row, error } = await supabase.from("cases").insert(data).select().single();
    if (error) throw error;
    logEvent('case.created', { entityType: 'case', entityId: row.id, entityName: row.title });
    await fetchCases();
    notifyManagers("New case created", `Case "${row.title}" has been submitted and needs review.`);
    return row;
  }

  async function updateCase(id, updates) {
    let _oldStatus = null;
    if (updates.status) {
      const { data: _old } = await supabase.from('cases').select('status').eq('id', id).single();
      _oldStatus = _old?.status ?? null;
    }
    const { data: rows, error } = await supabase.from("cases").update(updates).eq("id", id).select();
    const row = rows?.[0] ?? null;
    if (error) throw error;
    await fetchCases();
    if (updates.status) {
      const { data: { user } } = await supabase.auth.getUser();
      const STATUS_LABELS = {
        open: "Open", in_progress: "In Progress", on_hold: "On Hold",
        technical_test: "Technical Test", functional_test: "Functional Test",
        user_test: "User Test (UAT)", completed: "Completed", cancelled: "Cancelled",
        estimated: "Estimated", assigned: "Assigned",
      };
      const label = STATUS_LABELS[updates.status] ?? updates.status.replace(/_/g, " ");
      const TEST_MSG = {
        technical_test:  "The case has moved to Technical Testing — verify code correctness and edge cases.",
        functional_test: "The case has moved to Functional Testing — validate against the functional specification.",
        user_test:       "The case is ready for User Acceptance Testing (UAT) — business sign-off required.",
      };
      const body = TEST_MSG[updates.status] ?? `Case status changed to "${label}".`;
      notifyCaseParticipants(id, user?.id, `Status → ${label}`, body, { case_id: id, event_type: "status_change" });
      logEvent('case.status_changed', { userId: user.id, userEmail: user.email, entityType: 'case', entityId: id, entityName: rows?.[0]?.title, oldValue: { status: _oldStatus }, newValue: { status: updates.status } });
    }
    return row;
  }

  async function deleteCase(id) {
    const { error } = await supabase.from("cases").delete().eq("id", id);
    if (error) throw error;
    await fetchCases();
  }

  return { cases, loading, error, createCase, updateCase, deleteCase, refetch: fetchCases };
}

function useApplications(caseId = null) {
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchApps = useCallback(async () => {
    setLoading(true);
    let query = supabase
      .from("applications")
      .select(`
        *,
        consultant:consultant_id(id, full_name, email, avatar_url,
          consultant_profiles(headline, skills, hourly_rate, years_experience,
            external_occupancy_pct, travel_available)),
        case:case_id(id, title, status, project:project_id(id, name, avatar_url, client:client_id(id, avatar_url)), client:client_id(id, avatar_url, client_profiles(company_name)))
      `)
      .order("submitted_at", { ascending: false });
    if (caseId) query = query.eq("case_id", caseId);
    const { data } = await query;
    setApplications(data ?? []);
    setLoading(false);
  }, [caseId]);

  useEffect(() => { fetchApps(); }, [fetchApps]);

  async function apply({ caseId: cId, coverLetter, proposedRate, timeCommitment }) {
    const { data: { user } } = await supabase.auth.getUser();
    const { data, error } = await supabase.from("applications").insert({
      case_id: cId, consultant_id: user.id,
      cover_letter: coverLetter, proposed_rate: proposedRate,
      time_commitment: timeCommitment,
    }).select().single();
    if (error) throw error;
    await fetchApps();
    notifyManagers("New application received", `A consultant applied to a case. Review in the applications section.`);
    return data;
  }

  async function reviewApplication(appId, status, notes) {
    const { data: { user } } = await supabase.auth.getUser();
    const { data, error } = await supabase.from("applications")
      .update({ status, notes, reviewed_at: new Date().toISOString(), reviewed_by: user.id })
      .eq("id", appId).select().single();
    if (error) throw error;
    if (status === "accepted") {
      const app = applications.find(a => a.id === appId);
      if (app) {
        await supabase.from("case_assignments").upsert({
          case_id: app.case_id, consultant_id: app.consultant_id,
          time_commitment: app.time_commitment,
        });
        notify(app.consultant_id, "Application accepted", "Your application has been accepted. You are now assigned to the case.");
      }
    } else if (status === "rejected") {
      const app = applications.find(a => a.id === appId);
      if (app) notify(app.consultant_id, "Application not selected", "Your application was reviewed but was not selected for this case.");
    }
    await fetchApps();
    return data;
  }

  async function withdraw(appId) {
    const { error } = await supabase.from("applications")
      .update({ status: "withdrawn" }).eq("id", appId);
    if (error) throw error;
    await fetchApps();
  }

  return { applications, loading, apply, reviewApplication, withdraw, refetch: fetchApps };
}

function useRatings(consultantId = null) {
  const [ratings, setRatings]     = useState([]);
  const [avgRating, setAvgRating] = useState(null);
  const [loading, setLoading]     = useState(true);

  useEffect(() => {
    if (!consultantId) return;
    (async () => {
      setLoading(true);
      const { data } = await supabase.from("case_ratings")
        .select("id, case_id, scores, comment, created_at, rater:rater_id(full_name, avatar_url), case:case_id(title)")
        .eq("ratee_id", consultantId)
        .eq("ratee_role", "consultant")
        .order("created_at", { ascending: false });
      const mapped = (data ?? []).map(r => {
        const vals = Object.values(r.scores ?? {});
        const score = vals.length > 0
          ? parseFloat((vals.reduce((s, v) => s + v, 0) / vals.length).toFixed(2))
          : 0;
        return { ...r, score };
      });
      setRatings(mapped);
      const positiveScores = mapped.map(r => r.score).filter(s => s > 0);
      setAvgRating(
        positiveScores.length > 0
          ? parseFloat((positiveScores.reduce((a, b) => a + b, 0) / positiveScores.length).toFixed(2))
          : null
      );
      setLoading(false);
    })();
  }, [consultantId]);

  async function submitRating({ caseId, score, comment }) {
    const { data: { user } } = await supabase.auth.getUser();
    const scores = { overall: score };
    const { data, error } = await supabase.from("case_ratings").insert({
      case_id: caseId ?? null,
      rater_id: user.id,
      ratee_id: consultantId,
      rater_role: "client",
      ratee_role: "consultant",
      scores,
      comment: comment || null,
    }).select().single();
    if (error) throw error;
    const newEntry = { ...data, score, rater: { full_name: null } };
    const newRatings = [...ratings, newEntry];
    setRatings(newRatings);
    const sum = newRatings.reduce((a, r) => a + r.score, 0);
    setAvgRating(parseFloat((sum / newRatings.length).toFixed(2)));
    return data;
  }

  return { ratings, avgRating, loading, submitRating };
}

// ============================================================
// APPLICANT RANKING ENGINE
// ============================================================
function computeApplicantScore(app, caseData, pastAssignments, allRatings, clientWeights = null) {
  // Normalize client weights so they always sum to 100
  const RAW_W = clientWeights ?? { skills: 25, rating: 20, clientFamiliarity: 15, clientRating: 15, experience: 10, rate: 10, commitment: 5 };
  const wSum = Object.values(RAW_W).reduce((s, v) => s + (v || 0), 0) || 100;
  const wKeys = ["skills","rating","clientFamiliarity","clientRating","experience","rate","commitment"];
  let allocated = 0;
  const W = {};
  wKeys.forEach((k, i) => {
    if (i === wKeys.length - 1) { W[k] = 100 - allocated; }
    else { W[k] = Math.round(((RAW_W[k] ?? 0) / wSum) * 100); allocated += W[k]; }
  });

  const profile = Array.isArray(app.consultant?.consultant_profiles)
    ? app.consultant.consultant_profiles[0]
    : app.consultant?.consultant_profiles;
  const consultantSkills = profile?.skills ?? [];
  const required = [
    ...(caseData.skills_required ?? []),
    caseData.area_sap, caseData.area_industry,
  ].filter(Boolean);

  // 1. Skill match
  const matched = required.length
    ? required.filter(r => consultantSkills.some(s =>
        s.toLowerCase().includes(r.toLowerCase()) || r.toLowerCase().includes(s.toLowerCase())
      )).length
    : 0;
  const skillPts = required.length ? Math.round((matched / required.length) * W.skills) : Math.round(W.skills * 0.5);

  // 2. Overall avg rating
  const myRatings = allRatings.filter(r => r.consultant_id === app.consultant_id);
  const avgRating = myRatings.length ? myRatings.reduce((s, r) => s + r.score, 0) / myRatings.length : 0;
  const ratingPts = myRatings.length ? Math.round((avgRating / 5) * W.rating) : 0;

  // 3. Client familiarity
  const clientWork = (pastAssignments ?? []).filter(
    a => a.consultant_id === app.consultant_id && (a.case?.client_id ?? null) === caseData.client_id
  );
  const familiarityPts = clientWork.length ? W.clientFamiliarity : 0;

  // 4. Client-specific rating
  const clientCaseIds = new Set(clientWork.map(a => a.case_id));
  const clientRatings = myRatings.filter(r => clientCaseIds.has(r.case_id));
  const clientAvg = clientRatings.length ? clientRatings.reduce((s, r) => s + r.score, 0) / clientRatings.length : 0;
  const clientRatingPts = clientRatings.length ? Math.round((clientAvg / 5) * W.clientRating) : 0;

  // 5. Experience match
  const minExp = caseData.min_years_experience ?? 0;
  const theirExp = profile?.years_experience ?? 0;
  const expRatio = minExp === 0 ? 1 : theirExp >= minExp * 1.5 ? 1 : theirExp >= minExp ? 0.8 : theirExp >= minExp * 0.75 ? 0.4 : 0;
  const expPts = Math.round(expRatio * W.experience);

  // 6. Rate fit vs profile hourly rate
  const profileRate = profile?.hourly_rate;
  const proposed = app.proposed_rate;
  let rateRatio = 0.5;
  if (proposed && profileRate) {
    const r = proposed / profileRate;
    rateRatio = r <= 0.9 ? 1 : r <= 1.0 ? 0.8 : r <= 1.15 ? 0.5 : 0.2;
  }
  const ratePts = Math.round(rateRatio * W.rate);

  // 7. Time commitment vs available capacity (5 pts)
  // Score how much of their free capacity they're committing, not raw %.
  const maxAvail = app.max_available_at_submission ?? 100;
  const ratio = maxAvail > 0 ? (app.time_commitment ?? 0) / maxAvail : 0;
  const commitPts = !app.time_commitment ? 0
    : ratio >= 0.8 ? 5
    : ratio >= 0.6 ? 4
    : ratio >= 0.4 ? 3
    : ratio >= 0.2 ? 2
    : 1;
  const commitDetail = app.time_commitment
    ? `${app.time_commitment}% of ${maxAvail}% avail (${Math.round(ratio * 100)}%)`
    : "—";

  const total = skillPts + ratingPts + familiarityPts + clientRatingPts + expPts + ratePts + commitPts;
  return {
    ...app,
    totalScore: total,
    breakdown: {
      skills:            { pts: skillPts,        max: W.skills,            labelKey: "rank.label_skills",        detail: required.length ? `${matched}/${required.length} matched` : null, detailKey: required.length ? null : "rank.detail_no_req" },
      rating:            { pts: ratingPts,        max: W.rating,            labelKey: "rank.label_rating",        detail: myRatings.length ? `${avgRating.toFixed(1)}★ (${myRatings.length})` : null, detailKey: myRatings.length ? null : "rank.detail_no_ratings" },
      clientFamiliarity: { pts: familiarityPts,   max: W.clientFamiliarity, labelKey: "rank.label_client_exp",   detail: clientWork.length ? `${clientWork.length}× with client` : null, detailKey: clientWork.length ? null : "rank.detail_first_time" },
      clientRating:      { pts: clientRatingPts,  max: W.clientRating,      labelKey: "rank.label_client_rating", detail: clientRatings.length ? `${clientAvg.toFixed(1)}★ from client` : null, detailKey: clientRatings.length ? null : "rank.detail_no_client_ratings" },
      experience:        { pts: expPts,           max: W.experience,        labelKey: "rank.label_experience",    detail: minExp ? `${theirExp}y / min ${minExp}y` : `${theirExp}y exp` },
      rate:              { pts: ratePts,          max: W.rate,              labelKey: "rank.label_rate",          detail: proposed ? `$${proposed}/hr` : null, detailKey: proposed ? null : "rank.detail_not_specified" },
      commitment:        { pts: commitPts,        max: W.commitment,        labelKey: "rank.label_availability",  detail: commitDetail },
    },
  };
}

function useApplicantRanking(caseData, applications) {
  const [ranking, setRanking] = useState([]);
  const [loading, setLoading] = useState(false);
  const [clientSettings, setClientSettings] = useState(null);

  useEffect(() => {
    if (!caseData?.client_id) return;
    supabase.from("client_profiles")
      .select("assignment_settings")
      .eq("id", caseData.client_id)
      .maybeSingle()
      .then(({ data }) => setClientSettings(data?.assignment_settings ?? null));
  }, [caseData?.client_id]);

  useEffect(() => {
    if (!caseData?.id || !applications?.length) { setRanking([]); return; }
    const ids = [...new Set(applications.map(a => a.consultant_id))];
    (async () => {
      setLoading(true);
      const [{ data: rawRatings }, { data: assignments }] = await Promise.all([
        supabase.from("case_ratings").select("ratee_id, scores, case_id, case:case_id(client_id)").in("ratee_id", ids).eq("ratee_role", "consultant"),
        supabase.from("case_assignments").select("consultant_id, case_id, case:case_id(client_id)").in("consultant_id", ids),
      ]);
      const ratings = (rawRatings ?? []).map(r => {
        const vals = Object.values(r.scores ?? {});
        return { consultant_id: r.ratee_id, score: vals.length ? vals.reduce((s, v) => s + v, 0) / vals.length : 0, case_id: r.case_id, case: r.case };
      });
      const weights = clientSettings ? {
        skills:            clientSettings.weight_skills            ?? 25,
        rating:            clientSettings.weight_rating            ?? 20,
        clientFamiliarity: clientSettings.weight_client_familiarity ?? 15,
        clientRating:      clientSettings.weight_client_rating      ?? 15,
        experience:        clientSettings.weight_experience         ?? 10,
        rate:              clientSettings.weight_rate               ?? 10,
        commitment:        clientSettings.weight_commitment         ?? 5,
      } : null;
      const scored = applications
        .map(app => computeApplicantScore(app, caseData, assignments ?? [], ratings ?? [], weights))
        .sort((a, b) => b.totalScore - a.totalScore);
      setRanking(scored);
      setLoading(false);
    })();
  }, [caseData?.id, applications?.length, clientSettings]);
  return { ranking, loading, clientSettings };
}

function CaseFeedbackModal({ caseData, onClose }) {
  const { t } = useT();
  const consultants = caseData.case_assignments ?? [];
  const [ratings, setRatings] = useState(
    Object.fromEntries(consultants.map(a => [a.consultant_id, { score: 0, comment: "" }]))
  );
  const [saving, setSaving] = useState(false);

  async function handleSubmit() {
    setSaving(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      for (const a of consultants) {
        const r = ratings[a.consultant_id];
        if (r?.score > 0) {
          await supabase.from("ratings").upsert({
            consultant_id: a.consultant_id, case_id: caseData.id,
            rated_by: user.id, score: r.score, comment: r.comment || null, is_public: true,
          });
        }
      }
      onClose();
    } catch (e) { alert(e.message); }
    setSaving(false);
  }

  if (!consultants.length) return null;
  const hasAnyRating = Object.values(ratings).some(r => r.score > 0);

  return (
    <div className="fixed inset-0 bg-black/40 z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6 space-y-4 max-h-[90vh] overflow-y-auto">
        <div>
          <h2 className="font-bold text-lg text-gray-900">{t("feedback.title")}</h2>
          <p className="text-sm text-gray-400 mt-0.5">{t("feedback.subtitle").replace("{title}", caseData.title)}</p>
        </div>
        {consultants.map(a => {
          const r = ratings[a.consultant_id] ?? { score: 0, comment: "" };
          const name = a.users?.full_name ?? t("fallback.consultant");
          return (
            <div key={a.consultant_id} className="border border-gray-100 rounded-xl p-4 space-y-2">
              <div className="font-medium text-sm text-gray-900">{name}</div>
              <div className="flex gap-1">
                {[1, 2, 3, 4, 5].map(n => (
                  <button key={n} onClick={() => setRatings(p => ({ ...p, [a.consultant_id]: { ...p[a.consultant_id], score: n } }))}
                    className={`text-2xl transition-transform hover:scale-110 ${n <= r.score ? "text-yellow-400" : "text-gray-200"}`}><Star size={18} fill={n <= r.score ? "currentColor" : "none"} /></button>
                ))}
              </div>
              {r.score > 0 && (
                <textarea value={r.comment}
                  onChange={e => setRatings(p => ({ ...p, [a.consultant_id]: { ...p[a.consultant_id], comment: e.target.value } }))}
                  placeholder={t("feedback.comment_ph")} rows={2}
                  className="w-full text-sm border border-gray-200 rounded-lg p-2 resize-none focus:outline-none focus:ring-2 focus:ring-blue-500" />
              )}
            </div>
          );
        })}
        <div className="flex gap-2 pt-2">
          <button onClick={onClose} className="flex-1 py-2 text-sm text-gray-500 border border-gray-200 rounded-xl hover:bg-gray-50">{t("feedback.skip")}</button>
          <button onClick={handleSubmit} disabled={saving || !hasAnyRating}
            className="flex-1 py-2 text-sm font-semibold bg-blue-600 text-white rounded-xl hover:bg-blue-700 disabled:opacity-50">
            {saving ? t("state.saving") : t("feedback.submit")}
          </button>
        </div>
      </div>
    </div>
  );
}

const RANKING_CRITERIA = ["skills", "rating", "clientFamiliarity", "clientRating", "experience", "rate", "commitment"];

function ApplicantRankingSection({ caseData, auth, applications, reviewApplication }) {
  const { t } = useT();
  const { ranking, loading, clientSettings } = useApplicantRanking(caseData, applications);
  const overcommitTolerance = clientSettings?.max_overcommitment_tolerance ?? 0;
  const [liveAvailability, setLiveAvailability] = useState({});
  const [recalculating, setRecalculating]       = useState(false);
  const [lastRecalculated, setLastRecalculated] = useState(null);

  const TERMINAL_S = ["completed", "cancelled", "terminated", "closed", "approved"];

  const recalculate = useCallback(async () => {
    if (!applications.length) return;
    setRecalculating(true);
    const ids = [...new Set(applications.map(a => a.consultant_id))];
    const [{ data: profiles }, { data: assignments }] = await Promise.all([
      supabase.from("consultant_profiles")
        .select("id, external_occupancy_pct")
        .in("id", ids),
      supabase.from("case_assignments")
        .select("consultant_id, time_commitment, case:case_id(status)")
        .in("consultant_id", ids)
        .neq("case_id", caseData.id),
    ]);
    const extMap = Object.fromEntries((profiles ?? []).map(p => [p.id, p.external_occupancy_pct ?? 0]));
    const liveMap = {};
    for (const id of ids) {
      const active = (assignments ?? [])
        .filter(a => a.consultant_id === id && !TERMINAL_S.includes(a.case?.status))
        .reduce((sum, a) => sum + (a.time_commitment ?? 0), 0);
      liveMap[id] = Math.max(0, 100 - (extMap[id] ?? 0) - active);
    }
    setLiveAvailability(liveMap);
    setLastRecalculated(new Date());
    setRecalculating(false);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [caseData.id, applications.length]);

  useEffect(() => { recalculate(); }, [recalculate]);

  // Re-score ranking using live availability if available
  const hasLive = Object.keys(liveAvailability).length > 0;
  const displayRanking = hasLive
    ? ranking.map(app => {
        const live = liveAvailability[app.consultant_id] ?? (app.max_available_at_submission ?? 100);
        const ratio = live > 0 ? (app.time_commitment ?? 0) / live : 0;
        const commitPts = !app.time_commitment ? 0
          : ratio >= 0.8 ? 5 : ratio >= 0.6 ? 4 : ratio >= 0.4 ? 3 : ratio >= 0.2 ? 2 : 1;
        const oldCommit = app.breakdown.commitment.pts;
        return {
          ...app,
          liveAvailability: live,
          overcommitted: (app.time_commitment ?? 0) > live + overcommitTolerance,
          totalScore: app.totalScore - oldCommit + commitPts,
          breakdown: {
            ...app.breakdown,
            commitment: {
              ...app.breakdown.commitment,
              pts: commitPts,
              detail: `${app.time_commitment ?? 0}% of ${live}% now (${Math.round(ratio * 100)}%)`,
            },
          },
        };
      }).sort((a, b) => b.totalScore - a.totalScore)
    : ranking;

  const [autoAssigning, setAutoAssigning] = useState(false);

  async function runAutoAssign() {
    const candidate = displayRanking.find(a => !a.overcommitted && a.status === "pending");
    if (!candidate) return;
    setAutoAssigning(true);
    try { await reviewApplication(candidate.id, "accepted", "Auto-assigned by system"); }
    catch (e) { alert(e.message); }
    setAutoAssigning(false);
  }

  const windowDays = clientSettings?.application_window_days ?? 7;
  const windowClosed = caseData.created_at
    ? (Date.now() - new Date(caseData.created_at).getTime()) / 86400000 >= windowDays
    : false;
  const minApplicants = clientSettings?.min_applicants ?? 1;
  const pendingCount = applications.filter(a => a.status === "pending").length;
  const canAutoAssign = clientSettings?.auto_assign_enabled
    && (auth.isAdmin || auth.isManager)
    && windowClosed
    && pendingCount >= minApplicants;
  const autoAssignBlocked = clientSettings?.auto_assign_enabled
    && (auth.isAdmin || auth.isManager)
    && (!windowClosed || pendingCount < minApplicants);

  if (!applications.length) return <p className="text-sm text-gray-400 py-4">{t("rank.no_apps")}</p>;
  if (loading) return <Spinner />;
  const best = displayRanking[0];

  const fmtTime = d => {
    const diff = Math.round((Date.now() - d.getTime()) / 1000);
    if (diff < 5) return "just now";
    if (diff < 60) return `${diff}s ago`;
    return `${Math.round(diff / 60)}m ago`;
  };

  return (
    <div className="space-y-6">
      {/* Recommended consultant */}
      {best && (
        <div>
          <div className="flex items-center justify-between mb-3 gap-2 flex-wrap">
            <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide">{t("rank.recommended")}</p>
            <div className="flex items-center gap-2 flex-wrap">
              {lastRecalculated && (
                <span className="text-[10px] text-gray-400">{fmtTime(lastRecalculated)}</span>
              )}
              <button onClick={recalculate} disabled={recalculating}
                className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold bg-white border border-gray-200 text-gray-600 rounded-xl hover:bg-gray-50 hover:border-gray-300 disabled:opacity-50 transition-colors shadow-sm">
                <RotateCcw className={`w-3 h-3 ${recalculating ? "animate-spin" : ""}`} />
                {recalculating ? t("rank.recalculating") : t("rank.recalculate")}
              </button>
              {canAutoAssign && (
                <button onClick={runAutoAssign} disabled={autoAssigning}
                  className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold bg-purple-600 hover:bg-purple-700 text-white rounded-xl disabled:opacity-50 transition-colors shadow-sm">
                  <Wand2 className="w-3 h-3" />
                  {autoAssigning ? t("rank.assigning") : t("rank.auto_assign")}
                </button>
              )}
              {autoAssignBlocked && (
                <span className="text-[10px] text-amber-600 bg-amber-50 border border-amber-200 px-2 py-1 rounded-lg">
                  {!windowClosed
                    ? t("assign.window_closes").replace("{n}", Math.max(0, Math.ceil(windowDays - (Date.now() - new Date(caseData.created_at).getTime()) / 86400000)))
                    : (() => { const need = minApplicants - pendingCount; return t(need === 1 ? "assign.need_more_one" : "assign.need_more_many").replace("{n}", need); })()}
                </span>
              )}
            </div>
          </div>
          <div className="bg-gradient-to-br from-blue-50 to-indigo-50 border-2 border-blue-200 rounded-2xl p-5">
            <div className="flex items-center gap-4 mb-4">
              <PersonAvatar name={best.consultant?.full_name} avatarUrl={best.consultant?.avatar_url} size={48} />
              <div className="flex-1 min-w-0">
                <div className="font-bold text-gray-900">{best.consultant?.full_name}</div>
                <div className="text-xs text-gray-500">
                  {(Array.isArray(best.consultant?.consultant_profiles)
                    ? best.consultant.consultant_profiles[0]
                    : best.consultant?.consultant_profiles)?.headline ?? ""}
                </div>
              </div>
              <div className="text-right flex-shrink-0">
                <div className="text-2xl font-black text-blue-700">{best.totalScore}</div>
                <div className="text-xs text-gray-400">{t("rank.pts")}</div>
              </div>
            </div>
            {/* Live availability row for best */}
            {hasLive && (
              <div className={`flex items-center gap-3 mb-4 px-3 py-2 rounded-xl text-xs font-medium ${
                best.overcommitted
                  ? "bg-red-50 border border-red-200 text-red-700"
                  : "bg-white/70 text-gray-600"
              }`}>
                {best.overcommitted
                  ? <><AlertTriangle size={13} className="inline mr-1 flex-shrink-0" /><span>{t("assign.avail_conflict").replace("{pct}", best.time_commitment).replace("{free}", best.liveAvailability)}</span></>
                  : <><Check size={13} className="inline mr-1 flex-shrink-0" /><span>{t("assign.avail_current").replace("{free}", best.liveAvailability).replace("{pct}", best.time_commitment)}</span></>
                }
              </div>
            )}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 mb-4">
              {RANKING_CRITERIA.map(key => {
                const c = best.breakdown[key];
                const pct = Math.round((c.pts / c.max) * 100);
                return (
                  <div key={key} className="bg-white/80 rounded-xl p-2.5">
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-[10px] font-semibold text-gray-400 uppercase tracking-wide truncate">{t(c.labelKey)}</span>
                      <span className="text-xs font-bold text-blue-700 ml-1 flex-shrink-0">{c.pts}/{c.max}</span>
                    </div>
                    <div className="h-1 bg-gray-100 rounded-full mb-1">
                      <div className="h-full rounded-full" style={{ width: `${pct}%`, backgroundColor: pct >= 80 ? "#22c55e" : pct >= 50 ? "#3b82f6" : pct >= 25 ? "#f59e0b" : "#ef4444" }} />
                    </div>
                    <div className="text-[10px] text-gray-400 truncate">{c.detailKey ? t(c.detailKey) : c.detail}</div>
                  </div>
                );
              })}
            </div>
            {(auth.isAdmin || auth.isManager) && best.status === "pending" && (
              <button onClick={() => reviewApplication(best.id, "accepted")}
                className="w-full py-2 bg-blue-600 text-white text-sm font-semibold rounded-xl hover:bg-blue-700">
                {t("rank.accept_top")}
              </button>
            )}
          </div>
        </div>
      )}

      {/* All applicants ranked */}
      <div>
        <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide mb-3">{t("rank.all_ranked")}</p>
        <div className="space-y-3">
          {displayRanking.map((app, i) => {
            const profile = Array.isArray(app.consultant?.consultant_profiles)
              ? app.consultant.consultant_profiles[0]
              : app.consultant?.consultant_profiles;
            const medal = i === 0 ? <Trophy size={14} className="text-yellow-500" /> : i === 1 ? <span className="text-[11px] font-bold text-slate-400">2</span> : i === 2 ? <span className="text-[11px] font-bold text-amber-600">3</span> : `#${i + 1}`;
            const conflict = hasLive && app.overcommitted;
            return (
              <div key={app.id} className={`border rounded-xl p-4 ${
                conflict ? "border-red-200 bg-red-50/30"
                : i === 0 ? "border-blue-200 bg-blue-50/30"
                : "border-gray-100 bg-white"
              }`}>
                <div className="flex items-center gap-3 mb-3">
                  <div className="w-8 h-8 rounded-full bg-gray-100 flex items-center justify-center font-bold text-sm flex-shrink-0">{medal}</div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-semibold text-sm text-gray-900">{app.consultant?.full_name}</span>
                      {conflict && (
                        <span className="px-1.5 py-0.5 bg-red-100 text-red-700 text-[10px] font-bold rounded"><AlertTriangle size={9} className="inline mr-0.5" />{t("rank.overcommitted")}</span>
                      )}
                    </div>
                    <div className="text-xs text-gray-400">{profile?.headline ?? (profile?.years_experience ? `${profile.years_experience}y exp` : "")}</div>
                  </div>
                  <div className="text-right flex-shrink-0">
                    <div className="font-black text-gray-900 text-lg">{app.totalScore}<span className="text-xs font-normal text-gray-400">/100</span></div>
                    <Badge className={APP_STATUS_COLORS[app.status]}>{STATUS_LABEL_KEYS[app.status] ? t(STATUS_LABEL_KEYS[app.status]) : cap(app.status)}</Badge>
                  </div>
                </div>
                {/* Live availability bar */}
                {hasLive && (
                  <div className="flex items-center gap-2 mb-3 text-xs">
                    <span className="text-gray-400 flex-shrink-0">{t("rank.avail_now")}</span>
                    <div className="flex-1 h-1.5 bg-gray-100 rounded-full overflow-hidden">
                      <div className="h-full rounded-full transition-all"
                        style={{ width: `${app.liveAvailability}%`, backgroundColor: app.liveAvailability === 0 ? "#ef4444" : app.liveAvailability < (app.time_commitment ?? 0) ? "#f59e0b" : "#22c55e" }} />
                    </div>
                    <span className={`font-semibold flex-shrink-0 ${conflict ? "text-red-600" : "text-gray-700"}`}>{app.liveAvailability}%</span>
                    <span className="text-gray-400 flex-shrink-0">· committed {app.time_commitment ?? 0}%</span>
                  </div>
                )}
                {/* Score bars */}
                <div className="flex gap-1 mb-3" title={t("rank.score_tooltip")}>
                  {RANKING_CRITERIA.map(key => {
                    const c = app.breakdown[key];
                    const pct = Math.round((c.pts / c.max) * 100);
                    const clabel = t(c.labelKey);
                    const cdetail = c.detailKey ? t(c.detailKey) : c.detail;
                    return (
                      <div key={key} className="flex-1" title={`${clabel}: ${c.pts}/${c.max} — ${cdetail}`}>
                        <div className="h-8 bg-gray-100 rounded relative overflow-hidden">
                          <div className="absolute bottom-0 w-full rounded transition-all"
                            style={{ height: `${pct}%`, backgroundColor: pct >= 80 ? "#22c55e" : pct >= 50 ? "#3b82f6" : pct >= 25 ? "#f59e0b" : "#ef4444" }} />
                        </div>
                        <div className="text-[8px] text-gray-400 text-center mt-0.5 truncate">{clabel.split(" ")[0]}</div>
                      </div>
                    );
                  })}
                </div>
                {app.cover_letter && <p className="text-xs text-gray-500 mb-2 line-clamp-1 italic">"{app.cover_letter}"</p>}
                {(auth.isAdmin || auth.isManager) && app.status === "pending" && (
                  <div className="flex gap-2">
                    <button onClick={() => reviewApplication(app.id, "accepted")} className="px-3 py-1 bg-green-600 text-white text-xs rounded-lg hover:bg-green-700">{t("action.accept")}</button>
                    <button onClick={() => reviewApplication(app.id, "rejected")} className="px-3 py-1 bg-red-100 text-red-700 text-xs rounded-lg hover:bg-red-200">{t("action.reject")}</button>
                    <button onClick={() => reviewApplication(app.id, "under_review")} className="px-3 py-1 bg-blue-100 text-blue-700 text-xs rounded-lg hover:bg-blue-200">{t("action.review")}</button>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function useFavorites() {
  const [favorites, setFavorites] = useState([]);

  useEffect(() => {
    (async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;
      const { data } = await supabase.from("favorites")
        .select("case_id").eq("consultant_id", user.id);
      setFavorites(data?.map(f => f.case_id) ?? []);
    })();
  }, []);

  function isFavorite(caseId) { return favorites.includes(caseId); }

  async function toggle(caseId) {
    const { data: { user } } = await supabase.auth.getUser();
    if (isFavorite(caseId)) {
      await supabase.from("favorites")
        .delete().eq("consultant_id", user.id).eq("case_id", caseId);
      setFavorites(prev => prev.filter(id => id !== caseId));
    } else {
      await supabase.from("favorites").insert({ consultant_id: user.id, case_id: caseId });
      setFavorites(prev => [...prev, caseId]);
    }
  }

  return { favorites, isFavorite, toggle };
}

function useFollowedClients() {
  const [followed, setFollowed] = useState([]);

  useEffect(() => {
    (async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;
      const { data } = await supabase.from("followed_clients")
        .select("client_user_id").eq("consultant_id", user.id);
      setFollowed(data?.map(f => f.client_user_id) ?? []);
    })();
  }, []);

  function isFollowing(clientUserId) { return !!clientUserId && followed.includes(clientUserId); }

  async function toggle(clientUserId) {
    if (!clientUserId) return;
    const { data: { user } } = await supabase.auth.getUser();
    if (isFollowing(clientUserId)) {
      await supabase.from("followed_clients")
        .delete().eq("consultant_id", user.id).eq("client_user_id", clientUserId);
      setFollowed(prev => prev.filter(id => id !== clientUserId));
    } else {
      await supabase.from("followed_clients")
        .insert({ consultant_id: user.id, client_user_id: clientUserId });
      setFollowed(prev => [...prev, clientUserId]);
    }
  }

  return { followed, isFollowing, toggle };
}

function useConsultantProfile(consultantId, profileId) {
  const [profile, setProfile]       = useState(null);
  const [availability, setAvailability] = useState(null);
  const [loading, setLoading]       = useState(true);
  const [profileError, setProfileError] = useState(null);

  const resolvedId = profileId ?? consultantId;

  const fetchProfile = useCallback(async () => {
    if (!resolvedId) return;
    setLoading(true);
    setProfileError(null);

    // Avoid the case_assignments nested join — it requires a FK from case_assignments
    // to consultant_profiles which may not exist. Fetch core + safe related tables only.
    const { data, error } = await supabase.from("consultant_profiles")
      .select(`*, work_authorizations(*), consultant_customers(*), consultant_projects(*)`)
      .eq("id", resolvedId)
      .maybeSingle();

    if (error) {
      setProfileError(error.message);
      console.error("fetchProfile error:", error.message);
    } else {
      setProfile(data ?? null);
    }

    const { data: avail } = await supabase.rpc("get_consultant_availability",
      { p_consultant_id: resolvedId });
    setAvailability(avail);
    setLoading(false);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [resolvedId]);

  useEffect(() => { fetchProfile(); }, [fetchProfile]);

  async function updateProfile(updates) {
    const { data: updated, error } = await supabase.from("consultant_profiles")
      .update(updates).eq("id", resolvedId).select("id");
    if (error) throw error;
    if (!updated || updated.length === 0) {
      // No row exists yet — insert for first time
      const { error: ie } = await supabase.from("consultant_profiles")
        .insert({ id: resolvedId, ...updates });
      if (ie) throw new Error(`Profile create failed: ${ie.message}`);
    }
    await fetchProfile();
  }

  async function addCustomer(data) {
    const { error } = await supabase.from("consultant_customers")
      .insert({ ...data, consultant_id: resolvedId });
    if (error) throw error;
    await fetchProfile();
  }

  async function addProject(data) {
    const { error } = await supabase.from("consultant_projects")
      .insert({ ...data, consultant_id: resolvedId });
    if (error) throw error;
    await fetchProfile();
  }

  async function addWorkAuth(data) {
    const { error } = await supabase.from("work_authorizations")
      .insert({ ...data, consultant_id: resolvedId });
    if (error) throw error;
    await fetchProfile();
  }

  async function uploadPhoto(file) {
    const ext = file.name.split(".").pop().toLowerCase();
    const path = `consultant-avatars/${consultantId}.${ext}`;
    const { error: upErr } = await supabase.storage.from("project-avatars").upload(path, file, { upsert: true });
    if (upErr) throw upErr;
    const { data: { publicUrl } } = supabase.storage.from("project-avatars").getPublicUrl(path);
    await updateProfile({ photo_url: publicUrl });
    await supabase.from("users").update({ avatar_url: publicUrl }).eq("id", consultantId);
    return publicUrl;
  }

  return { profile, availability, loading, profileError, updateProfile, uploadPhoto, addCustomer, addProject, addWorkAuth, refetch: fetchProfile };
}

// ── Notification helpers ─────────────────────────────────────
async function notify(userId, title, body) {
  if (!userId) return;
  try { await supabase.from("notifications").insert({ user_id: userId, title, body, is_read: false }); } catch (_) {}
}
async function notifyManagers(title, body) {
  try {
    const { data } = await supabase.from("users").select("id").in("role", ["admin","manager"]).eq("is_active", true);
    if (!data?.length) return;
    await supabase.from("notifications").insert(data.map(u => ({ user_id: u.id, title, body, is_read: false })));
  } catch (_) {}
}
async function notifyCaseParticipants(caseId, excludeUserId, title, body, opts = {}) {
  try {
    const { data: c } = await supabase.from("cases")
      .select("client_id, manager_id, case_key_users(user_id), case_assignments(consultant_id)").eq("id", caseId).single();
    if (!c) return;
    const ids = new Set();
    if (c.client_id  && c.client_id  !== excludeUserId) ids.add(c.client_id);
    if (c.manager_id && c.manager_id !== excludeUserId) ids.add(c.manager_id);
    (c.case_key_users  ?? []).forEach(ku => { if (ku.user_id      !== excludeUserId) ids.add(ku.user_id); });
    (c.case_assignments ?? []).forEach(a  => { if (a.consultant_id !== excludeUserId) ids.add(a.consultant_id); });
    if (!ids.size) return;
    await supabase.from("notifications").insert([...ids].map(uid => ({
      user_id: uid, title, body, is_read: false,
      case_id: opts.case_id ?? caseId ?? null,
      event_type: opts.event_type ?? "general",
    })));
  } catch (_) {}
}
