function getLifecycleStages(lifecycle, templates) {
  function resolvePreset(preset) {
    if (templates?.length) {
      const tmpl = templates.find(t => t.key === preset);
      if (tmpl) return tmpl.stages;
    }
    return LIFECYCLE_PRESETS[preset]?.stages ?? LIFECYCLE_PRESETS.standard.stages;
  }
  if (!lifecycle) return resolvePreset("standard");
  if (lifecycle.preset && lifecycle.preset !== "custom") return resolvePreset(lifecycle.preset);
  return lifecycle.stages?.length ? lifecycle.stages : resolvePreset("standard");
}

function useLifecycleTemplates() {
  const [templates, setTemplates] = useState([]);
  const [loadingTmpl, setLoadingTmpl] = useState(true);

  async function fetchTemplates() {
    setLoadingTmpl(true);
    const { data } = await supabase.from("lifecycle_templates")
      .select("*").eq("is_active", true).order("sort_order");
    setTemplates(data ?? []);
    setLoadingTmpl(false);
  }

  useEffect(() => { fetchTemplates(); }, []);

  function getTemplateStages(preset) {
    const tmpl = templates.find(t => t.key === preset);
    if (tmpl) return tmpl.stages;
    return LIFECYCLE_PRESETS[preset]?.stages ?? LIFECYCLE_PRESETS.standard.stages;
  }

  return { templates, loadingTmpl, fetchTemplates, getTemplateStages };
}

async function runStartDateMonitor(auth, cases) {
  const todayMs = Date.now();
  const todayStr = new Date().toISOString().slice(0, 10);
  const assignedWithStart = cases.filter(c => c.status === "assigned" && c.start_date);
  if (!assignedWithStart.length) return;

  const clientIds = [...new Set(assignedWithStart.map(c => c.client_id).filter(Boolean))];
  const settingsMap = {};
  if (clientIds.length) {
    try {
      const { data } = await supabase.from("client_profiles")
        .select("id, assignment_settings").in("id", clientIds);
      (data ?? []).forEach(cp => { settingsMap[cp.id] = cp.assignment_settings ?? {}; });
    } catch (_) {}
  }
  const SD = {
    start_reminders_enabled: true, start_reminder_1_days: 3, start_reminder_2_days: 1,
    start_overdue_action: "auto_start", start_overdue_grace_hours: 24,
  };

  for (const c of assignedWithStart) {
    const s = { ...SD, ...(settingsMap[c.client_id] ?? {}) };
    if (!s.start_reminders_enabled) continue;
    const startMs = new Date(c.start_date + "T00:00:00").getTime();
    const daysUntil = Math.ceil((startMs - todayMs) / 86400000);
    const hoursOverdue = daysUntil <= 0 ? (todayMs - startMs) / 3600000 : 0;
    const consultants = (c.case_assignments ?? []).map(a => a.consultant_id).filter(Boolean);

    if (daysUntil <= s.start_reminder_1_days && daysUntil > s.start_reminder_2_days) {
      const key = `sdrem1_${c.id}`;
      if (!localStorage.getItem(key)) {
        localStorage.setItem(key, todayStr);
        for (const uid of consultants)
          await notify(uid, "Case Starting Soon",
            `"${c.title}" starts in ${daysUntil} day${daysUntil !== 1 ? "s" : ""} (${c.start_date}). Please be ready to begin on time.`);
      }
    }

    if (daysUntil <= s.start_reminder_2_days && daysUntil > 0) {
      const key = `sdrem2_${c.id}`;
      if (!localStorage.getItem(key)) {
        localStorage.setItem(key, todayStr);
        for (const uid of consultants)
          await notify(uid, daysUntil === 1 ? "Case Starts Tomorrow" : "Case Starting Today",
            `"${c.title}" must start by ${c.start_date}. If not started in time it may be auto-progressed or reassigned.`);
        await notifyManagers("Case Starting Soon",
          `"${c.title}" is set to begin in ${daysUntil} day${daysUntil !== 1 ? "s" : ""}. Current status: Assigned.`);
      }
    }

    if (daysUntil < 0 && hoursOverdue >= s.start_overdue_grace_hours && (auth.isAdmin || auth.isManager)) {
      const key = `sdovr_${c.id}`;
      if (!localStorage.getItem(key)) {
        localStorage.setItem(key, todayStr);
        const daysLate = Math.floor(hoursOverdue / 24);
        if (s.start_overdue_action === "auto_start") {
          await supabase.from("cases").update({ status: "in_progress" }).eq("id", c.id);
          for (const uid of consultants)
            await notify(uid, "Case Auto-Started", `"${c.title}" was automatically moved to In Progress as the start date has passed.`);
          await notifyManagers("Case Auto-Started", `"${c.title}" was automatically moved to In Progress — start date ${c.start_date} has passed.`);
        } else if (s.start_overdue_action === "auto_unassign") {
          await supabase.from("case_assignments").delete().eq("case_id", c.id);
          await supabase.from("cases").update({ status: "open" }).eq("id", c.id);
          for (const uid of consultants)
            await notify(uid, "Assignment Removed", `Your assignment to "${c.title}" was removed — work was not started by the planned date (${c.start_date}).`);
          await notifyManagers("Case Unassigned", `"${c.title}" was unassigned — consultant did not start by ${c.start_date}.`);
        } else {
          await notifyManagers("Case Start Overdue",
            `"${c.title}" is ${daysLate} day${daysLate !== 1 ? "s" : ""} overdue. Still in Assigned status.`);
        }
      }
    }
  }
}

function useStartDateMonitor(auth, cases) {
  const fired = useRef(false);
  useEffect(() => {
    if (!auth?.user?.id || !cases.length || fired.current) return;
    fired.current = true;
    runStartDateMonitor(auth, cases);
    runDueDateMonitor(cases);
  }, [auth?.user?.id, cases.length]);
}

async function runDueDateMonitor(cases) {
  const todayMs = Date.now();
  const TERMINAL = ["completed","cancelled","terminated","closed","approved"];
  const active = cases.filter(c => c.due_date && !TERMINAL.includes(c.status));
  for (const c of active) {
    const dueMs = new Date(c.due_date + "T00:00:00").getTime();
    const daysLeft = Math.ceil((dueMs - todayMs) / 86400000);
    const lsKey3 = `duerem3_${c.id}`, lsKey1 = `duerem1_${c.id}`;
    if (daysLeft === 3 && !localStorage.getItem(lsKey3)) {
      localStorage.setItem(lsKey3, "1");
      notifyCaseParticipants(c.id, null, "Due date in 3 days", `"${c.title}" is due on ${c.due_date} — 3 days remaining.`, { case_id: c.id, event_type: "due_date" });
      notifyManagers("Due date approaching", `"${c.title}" is due in 3 days (${c.due_date}).`);
    }
    if (daysLeft <= 1 && daysLeft >= 0 && !localStorage.getItem(lsKey1)) {
      localStorage.setItem(lsKey1, "1");
      const when = daysLeft === 0 ? "today" : "tomorrow";
      notifyCaseParticipants(c.id, null, `Due date ${when}`, `"${c.title}" is due ${when} (${c.due_date}).`, { case_id: c.id, event_type: "due_date" });
      notifyManagers("Due date urgent", `"${c.title}" is due ${when} (${c.due_date}) and is still in progress.`);
    }
    if (daysLeft < 0 && !localStorage.getItem(`dueoverdue_${c.id}`)) {
      localStorage.setItem(`dueoverdue_${c.id}`, "1");
      notifyManagers("Case overdue", `"${c.title}" passed its due date (${c.due_date}) and is still open.`);
    }
  }
}

const SLA_PRIORITIES = [
  { key: "critical", label: "Critical", dot: "bg-red-500",    badge: "bg-red-50 text-red-700 border border-red-200"         },
  { key: "high",     label: "High",     dot: "bg-orange-500", badge: "bg-orange-50 text-orange-700 border border-orange-200" },
  { key: "medium",   label: "Medium",   dot: "bg-yellow-500", badge: "bg-yellow-50 text-yellow-700 border border-yellow-200" },
  { key: "low",      label: "Low",      dot: "bg-slate-400",  badge: "bg-slate-50 text-slate-600 border border-slate-200"    },
];

const SLA_DEFAULT_TYPES = [
  { key: "general",        labelKey: "sla.type_general",   label: "General Information" },
  { key: "problem",        labelKey: "sla.type_problem",   label: "Problem"             },
  { key: "change_request", labelKey: "sla.type_change_req",label: "Change Request"      },
];

function makeDefaultMatrix(keys) {
  const seed = {
    general:        { critical:{response:1,response_unit:"hours",resolution:8,resolution_unit:"hours"}, high:{response:8,response_unit:"hours",resolution:1,resolution_unit:"days"},  medium:{response:1,response_unit:"days",resolution:3,resolution_unit:"days"},  low:{response:3,response_unit:"days",resolution:8,resolution_unit:"days"} },
    problem:        { critical:{response:30,response_unit:"minutes",resolution:2,resolution_unit:"hours"}, high:{response:2,response_unit:"hours",resolution:8,resolution_unit:"hours"}, medium:{response:4,response_unit:"hours",resolution:2,resolution_unit:"days"},  low:{response:8,response_unit:"hours",resolution:5,resolution_unit:"days"} },
    change_request: { critical:{response:30,response_unit:"minutes",resolution:4,resolution_unit:"hours"}, high:{response:8,response_unit:"hours",resolution:1,resolution_unit:"days"},  medium:{response:1,response_unit:"days",resolution:3,resolution_unit:"days"},  low:{response:3,response_unit:"days",resolution:1,resolution_unit:"weeks"} },
  };
  const blank = Object.fromEntries(SLA_PRIORITIES.map(p => [p.key, { response:4, response_unit:"hours", resolution:1, resolution_unit:"days" }]));
  return Object.fromEntries((keys ?? SLA_DEFAULT_TYPES.map(t => t.key)).map(k => [k, seed[k] ?? blank]));
}

const SLA_UNIT_LABELS = { minutes: "min", hours: "h", days: "d", weeks: "wk" };

function SlaMatrixEditor({ caseTypes, matrix, editing, onChangeCaseTypes, onChangeMatrix }) {
  const { t } = useT();
  const UNITS = ["minutes", "hours", "days", "weeks"];

  function setCellField(ctKey, pKey, field, value) {
    onChangeMatrix(prev => ({
      ...prev,
      [ctKey]: { ...(prev[ctKey] ?? {}), [pKey]: { ...(prev[ctKey]?.[pKey] ?? {}), [field]: value } }
    }));
  }

  function addCaseType() {
    const key = `type_${caseTypes.length + 1}`;
    onChangeCaseTypes(prev => [...prev, { key, label: t("sla.new_type_label") }]);
    onChangeMatrix(prev => ({
      ...prev,
      [key]: Object.fromEntries(SLA_PRIORITIES.map(p => [p.key, { response:4, response_unit:"hours", resolution:1, resolution_unit:"days" }]))
    }));
  }

  function removeCaseType(key) {
    onChangeCaseTypes(prev => prev.filter(ct => ct.key !== key));
    onChangeMatrix(prev => { const n = { ...prev }; delete n[key]; return n; });
  }

  return (
    <div className="overflow-x-auto rounded-xl border border-gray-100">
      <table className="w-full text-sm border-collapse min-w-[500px]">
        <thead>
          <tr>
            <th className="text-left px-4 py-3 font-semibold text-gray-500 bg-gray-50 w-28 border-b border-gray-100">
              {t("sla.col_priority")}
            </th>
            {caseTypes.map(ct => (
              <th key={ct.key} className="px-4 py-3 bg-gray-50 border-b border-l border-gray-100 text-center">
                {editing ? (
                  <div className="flex items-center gap-1 min-w-[120px]">
                    <input
                      className="flex-1 text-xs font-semibold bg-white border border-gray-200 rounded-lg px-2 py-1 text-center min-w-0"
                      value={ct.label}
                      onChange={e => onChangeCaseTypes(prev => prev.map(c => c.key === ct.key ? { ...c, label: e.target.value } : c))}
                    />
                    {caseTypes.length > 1 && (
                      <button onClick={() => removeCaseType(ct.key)} className="text-gray-300 hover:text-red-400 flex-shrink-0">
                        <X size={13} />
                      </button>
                    )}
                  </div>
                ) : (
                  <span className="text-xs font-semibold text-gray-700">{ct.labelKey ? t(ct.labelKey) : ct.label}</span>
                )}
              </th>
            ))}
            {editing && (
              <th className="px-4 py-3 bg-gray-50 border-b border-l border-gray-100">
                <button onClick={addCaseType} className="text-xs text-blue-600 hover:text-blue-800 font-medium whitespace-nowrap">{t("sla.add_type")}</button>
              </th>
            )}
          </tr>
        </thead>
        <tbody>
          {SLA_PRIORITIES.map((p, pi) => (
            <tr key={p.key} className={pi % 2 === 0 ? "bg-white" : "bg-gray-50/40"}>
              <td className="px-4 py-3 border-b border-gray-100">
                <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold ${p.badge}`}>
                  <span className={`w-1.5 h-1.5 rounded-full flex-shrink-0 ${p.dot}`} />
                  {t(`priority.${p.key}`)}
                </span>
              </td>
              {caseTypes.map(ct => {
                const cell = matrix?.[ct.key]?.[p.key] ?? { response:4, response_unit:"hours", resolution:1, resolution_unit:"days" };
                return (
                  <td key={ct.key} className="px-4 py-3 border-b border-l border-gray-100">
                    {editing ? (
                      <div className="space-y-2">
                        {[["response", t("sla.col_response")],["resolution", t("sla.col_resolution")]].map(([field, lbl]) => (
                          <div key={field} className="flex items-center gap-1">
                            <span className="text-[10px] text-gray-400 w-16 shrink-0">{lbl}</span>
                            <input type="number" min="1"
                              className="w-12 text-xs border border-gray-200 rounded-lg px-1.5 py-1 text-center"
                              value={cell[field]}
                              onChange={e => setCellField(ct.key, p.key, field, Number(e.target.value))} />
                            <select
                              className="text-xs border border-gray-200 rounded-lg px-1 py-1 bg-white"
                              value={cell[`${field}_unit`]}
                              onChange={e => setCellField(ct.key, p.key, `${field}_unit`, e.target.value)}>
                              {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                            </select>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="space-y-1 text-center">
                        <div className="text-xs flex items-center justify-center gap-1">
                          <RotateCcw size={10} className="text-blue-400" />
                          <span className="font-medium text-gray-800">{cell.response}</span>
                          <span className="text-gray-400">{SLA_UNIT_LABELS[cell.response_unit]}</span>
                        </div>
                        <div className="text-xs flex items-center justify-center gap-1">
                          <Check size={10} className="text-green-500" />
                          <span className="font-medium text-gray-800">{cell.resolution}</span>
                          <span className="text-gray-400">{SLA_UNIT_LABELS[cell.resolution_unit]}</span>
                        </div>
                      </div>
                    )}
                  </td>
                );
              })}
              {editing && <td className="border-b border-l border-gray-100" />}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

