function VouchingPanel({ targetUserId, targetName }) {
  const auth = useAuth();
  const { t } = useT();
  const [vouches, setVouches] = useState([]);
  const [loading, setLoading] = useState(true);
  const [note, setNote] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [toast, setToast] = useState(null);

  const isPlatinum = auth.profile?.trust_level === 'platinum';
  const isSelf = auth.user?.id === targetUserId;

  useEffect(() => {
    if (!targetUserId) return;
    setLoading(true);
    supabase.from('user_vouches')
      .select('id, voucher_id, note, created_at, profiles!voucher_id(full_name)')
      .eq('vouchee_id', targetUserId)
      .order('created_at', { ascending: false })
      .then(({ data }) => {
        setVouches(data ?? []);
        setLoading(false);
      });
  }, [targetUserId]);

  const alreadyVouched = vouches.some(v => v.voucher_id === auth.user?.id);

  async function handleVouch() {
    setSubmitting(true);
    try {
      const { error } = await supabase.from('user_vouches').insert({
        voucher_id: auth.user.id,
        vouchee_id: targetUserId,
        note: note.trim() || null,
      });
      if (!error) {
        await supabase.rpc('recalculate_trust_level', { p_user_id: targetUserId });
        notify(targetUserId, 'Someone vouched for you', `${auth.profile?.full_name ?? 'A platinum consultant'} vouched for you.`);
        logEvent('vouch.submitted', { entityType: 'user', entityId: targetUserId, entityName: targetName });
        // Refresh vouches
        const { data } = await supabase.from('user_vouches')
          .select('id, voucher_id, note, created_at, profiles!voucher_id(full_name)')
          .eq('vouchee_id', targetUserId)
          .order('created_at', { ascending: false });
        setVouches(data ?? []);
        setNote('');
        setToast(t('vouch.submitted_toast'));
        setTimeout(() => setToast(null), 4000);
      }
    } catch (e) {
      // error is fire-and-forget
    }
    setSubmitting(false);
  }

  if (loading) return <div className="py-4 text-center text-gray-400 text-sm"><Spinner /></div>;

  return (
    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5 space-y-4">
      {/* Vouch count heading */}
      <div className="flex items-center justify-between">
        <h3 className="font-semibold text-gray-900 text-sm">{t('vouch.tab')}</h3>
        <span className="text-xs text-gray-500">{t('vouch.count').replace('{n}', vouches.length)}</span>
      </div>

      {/* Toast */}
      {toast && (
        <div className="bg-green-50 border border-green-200 rounded-xl px-4 py-2 text-sm text-green-700">{toast}</div>
      )}

      {/* Vouchers list */}
      {vouches.length === 0 ? (
        <p className="text-sm text-gray-400">{t('vouch.none')}</p>
      ) : (
        <div className="space-y-2">
          {vouches.map(v => (
            <div key={v.id} className="flex items-start gap-3 text-sm">
              <div className="w-7 h-7 rounded-xl bg-blue-50 flex items-center justify-center text-blue-600 font-bold text-xs flex-shrink-0">
                {(v.profiles?.full_name ?? '?')[0]}
              </div>
              <div className="min-w-0">
                <span className="font-medium text-gray-800">{v.profiles?.full_name ?? '—'}</span>
                {v.note && <p className="text-xs text-gray-500 mt-0.5 truncate">{v.note}</p>}
                <p className="text-xs text-gray-400">{new Date(v.created_at).toLocaleDateString()}</p>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Submit vouch — platinum only, not self */}
      {!isSelf && isPlatinum && (
        <div className="border-t border-gray-100 pt-4 space-y-3">
          <p className="text-xs font-semibold text-gray-700">{t('vouch.panel_title')}</p>
          {alreadyVouched ? (
            <p className="text-sm text-green-700">{t('vouch.already_vouched').replace('{name}', targetName ?? '')}</p>
          ) : (
            <>
              <textarea
                value={note}
                onChange={e => setNote(e.target.value)}
                rows={2}
                placeholder={t('vouch.note_ph')}
                className="w-full border border-gray-200 rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-blue-400 resize-none"
              />
              <button
                onClick={handleVouch}
                disabled={submitting}
                className="px-4 py-2 text-sm bg-blue-600 text-white rounded-xl hover:bg-blue-700 disabled:opacity-40">
                {submitting ? t('vouch.submitting') : t('vouch.submit')}
              </button>
            </>
          )}
        </div>
      )}
    </div>
  );
}

// ============================================================
// CONSULTANT PROFILE VIEW
// ============================================================
function ConsultantProfileView({ userId }) {
  const auth = useAuth();
  const { t } = useT();
  const targetUserId = userId ?? auth.profile?.id ?? auth.user?.id;
  const isOwnProfile = !userId || userId === auth.user?.id;

  const DEFAULT_THRESHOLDS = {
    silver:   { min_cases: 1,  min_avg_rating: 3.5 },
    gold:     { min_cases: 5,  min_avg_rating: 4.0 },
    platinum: { min_cases: 10, min_avg_rating: 4.5 },
  };

  const [section, setSection] = useState('overview');
  const [profileData, setProfileData]   = useState(null);
  const [cpData, setCpData]             = useState(null);
  const [ratingsData, setRatingsData]   = useState([]);
  const [dimensions, setDimensions]     = useState([]);
  const [assignedCount, setAssignedCount] = useState(0);
  const [activity, setActivity]         = useState([]);
  const [thresholds, setThresholds]     = useState(DEFAULT_THRESHOLDS);
  const [loading, setLoading]           = useState(true);
  const [error, setError]               = useState(null);
  const [uploadingAvatar, setUploadingAvatar] = useState(false);
  const avatarFileRef = useRef(null);

  async function handleAvatarUpload(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploadingAvatar(true);
    try {
      const ext = file.name.split('.').pop().toLowerCase();
      const path = `consultant-avatars/${targetUserId}.${ext}`;
      const { error: upErr } = await supabase.storage.from('project-avatars').upload(path, file, { upsert: true });
      if (upErr) throw upErr;
      const { data: { publicUrl } } = supabase.storage.from('project-avatars').getPublicUrl(path);
      await supabase.from('users').update({ avatar_url: publicUrl }).eq('id', targetUserId);
      await supabase.from('consultant_profiles').update({ photo_url: publicUrl }).eq('id', targetUserId);
      setProfileData(p => p ? { ...p, avatar_url: publicUrl } : p);
    } catch (err) { alert(`Avatar upload failed: ${err.message}`); }
    setUploadingAvatar(false);
    e.target.value = '';
  }

  useEffect(() => {
    if (!targetUserId) return;
    let cancelled = false;
    (async () => {
      setLoading(true);
      setError(null);
      try {
        const [profRes, ratingsRes, dimsRes, assignRes, logsRes, ssRes, cpRes] = await Promise.all([
          supabase.from('users')
            .select('id, full_name, email, role, trust_level, avg_rating, avatar_url, created_at')
            .eq('id', targetUserId).single(),
          supabase.from('case_ratings')
            .select('id, case_id, scores, created_at, cases(title)')
            .eq('ratee_id', targetUserId)
            .order('created_at', { ascending: false }),
          supabase.from('rating_dimensions')
            .select('key, label').eq('active', true).order('sort_order'),
          supabase.from('case_assignments')
            .select('id', { count: 'exact', head: true })
            .eq('consultant_id', targetUserId),
          supabase.from('audit_logs')
            .select('id, event_type, entity_name, created_at')
            .eq('user_id', targetUserId)
            .order('created_at', { ascending: false }).limit(5),
          supabase.from('system_settings')
            .select('key, value').eq('key', 'trust_thresholds').maybeSingle(),
          supabase.from('consultant_profiles')
            .select('headline, bio, linkedin_url, hourly_rate, years_experience, expertise_level, availability_type, travel_available, skills, external_occupancy_pct')
            .eq('id', targetUserId).maybeSingle(),
        ]);
        if (cancelled) return;
        setProfileData(profRes.data ?? null);
        setCpData(cpRes.data ?? null);
        setRatingsData(ratingsRes.data ?? []);
        setDimensions(dimsRes.data ?? []);
        setAssignedCount(assignRes.count ?? 0);
        setActivity(logsRes.data ?? []);
        if (ssRes.data?.value) {
          try {
            const parsed = typeof ssRes.data.value === 'string'
              ? JSON.parse(ssRes.data.value) : ssRes.data.value;
            setThresholds(parsed);
          } catch (_) {}
        }
      } catch (e) {
        if (!cancelled) setError(e.message ?? 'Failed to load profile.');
      }
      if (!cancelled) setLoading(false);
    })();
    return () => { cancelled = true; };
  }, [targetUserId]);

  // Compute averages from ratingsData
  const perRatingAvgs = ratingsData.map(r => {
    const vals = Object.values(r.scores ?? {});
    return vals.length > 0 ? vals.reduce((s, v) => s + v, 0) / vals.length : null;
  }).filter(v => v !== null);
  const overallAvg = perRatingAvgs.length > 0
    ? (perRatingAvgs.reduce((s, v) => s + v, 0) / perRatingAvgs.length).toFixed(2)
    : null;

  // Avg per dimension
  const dimAvgs = {};
  dimensions.forEach(d => {
    const vals = ratingsData.map(r => r.scores?.[d.key]).filter(v => v != null);
    dimAvgs[d.key] = vals.length > 0
      ? (vals.reduce((s, v) => s + v, 0) / vals.length).toFixed(2) : null;
  });

  // Group ratings by case for the history view
  const ratingsByCase = [];
  const seenCases = new Set();
  for (const r of ratingsData) {
    if (!seenCases.has(r.case_id)) {
      seenCases.add(r.case_id);
      ratingsByCase.push({ caseId: r.case_id, caseTitle: r.cases?.title ?? r.case_id, ratings: [] });
    }
    const group = ratingsByCase.find(g => g.caseId === r.case_id);
    if (group) group.ratings.push(r);
  }

  const tabs = [
    { id: 'overview',  label: t('profile.tab_overview') },
    { id: 'ratings',   label: t('profile.tab_ratings') },
    { id: 'tier',      label: t('profile.tab_tier') },
    { id: 'activity',  label: t('profile.tab_activity') },
    { id: 'vouches',   label: t('vouch.tab') },
    ...(isOwnProfile ? [{ id: 'edit', label: 'Profile' }] : []),
  ];

  if (loading) return <Spinner />;
  if (error) return (
    <div className="p-6 bg-red-50 rounded-2xl border border-red-200 text-red-600 text-sm">{error}</div>
  );

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
        <div className="flex items-center gap-4 flex-wrap">
          {isOwnProfile ? (
            <div className="relative group cursor-pointer flex-shrink-0" onClick={() => !uploadingAvatar && avatarFileRef.current?.click()}>
              <PersonAvatar name={profileData?.full_name} avatarUrl={profileData?.avatar_url} size={64} className="rounded-2xl" />
              <div className="absolute inset-0 rounded-2xl bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                {uploadingAvatar
                  ? <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin" />
                  : <Camera className="w-5 h-5 text-white" />}
              </div>
              <input ref={avatarFileRef} type="file" accept="image/*" onChange={handleAvatarUpload} className="hidden" />
            </div>
          ) : (
            <PersonAvatar name={profileData?.full_name} avatarUrl={profileData?.avatar_url} size={64} className="rounded-2xl" />
          )}
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 flex-wrap">
              <h1 className="text-xl font-bold text-gray-900">{profileData?.full_name ?? '—'}</h1>
              {profileData?.trust_level && <TrustBadge level={profileData.trust_level} size="sm" />}
            </div>
            {cpData?.headline && (
              <p className="text-sm font-medium text-gray-700 mt-0.5">{cpData.headline}</p>
            )}
            <div className="flex items-center gap-2 flex-wrap mt-1">
              <p className="text-xs text-gray-400 capitalize">
                {profileData?.role} · {t('profile.member_since')} {profileData?.created_at
                  ? new Date(profileData.created_at).toLocaleDateString() : '—'}
              </p>
              {profileData?.email && (
                <p className="text-xs text-gray-400">· {profileData.email}</p>
              )}
            </div>
            <div className="flex items-center gap-2 flex-wrap mt-2">
              {overallAvg && (
                <span className="text-xs flex items-center gap-1 text-yellow-600 font-semibold">
                  ★ {overallAvg}
                  <span className="text-gray-400 font-normal">({ratingsData.length})</span>
                </span>
              )}
              {cpData?.expertise_level && (
                <span className="px-2 py-0.5 bg-violet-100 text-violet-700 text-xs rounded-full capitalize">
                  {cpData.expertise_level.replace(/_/g, ' ')}
                </span>
              )}
              {cpData?.availability_type && (
                <span className="px-2 py-0.5 bg-teal-100 text-teal-700 text-xs rounded-full capitalize">
                  {cpData.availability_type.replace(/_/g, ' ')}
                </span>
              )}
              {cpData?.travel_available && (
                <span className="px-2 py-0.5 bg-blue-50 text-blue-600 text-xs rounded-full">Travel ✓</span>
              )}
              {cpData?.hourly_rate && (
                <span className="text-xs text-gray-500">${cpData.hourly_rate}/hr</span>
              )}
              {cpData != null && (
                <span className="text-xs text-emerald-600 font-medium">
                  {Math.max(0, 100 - (cpData.external_occupancy_pct ?? 0))}% free
                </span>
              )}
            </div>
          </div>
          {overallAvg && (
            <div className="text-right flex-shrink-0">
              <div className="text-2xl font-bold text-yellow-500">★ {overallAvg}</div>
              <div className="text-xs text-gray-400">{t('profile.overall_avg')}</div>
              <div className="text-xs text-gray-500 mt-0.5">
                {ratingsData.length} {t('profile.ratings_received')}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Tab bar */}
      <div className="flex gap-1 border-b border-gray-200 overflow-x-auto" style={{ scrollbarWidth: 'none' }}>
        {tabs.map(tabItem => (
          <button key={tabItem.id} onClick={() => setSection(tabItem.id)}
            className={`px-4 py-2 text-sm font-medium border-b-2 whitespace-nowrap transition-colors ${
              tabItem.id === section
                ? 'border-blue-600 text-blue-600'
                : 'border-transparent text-gray-500 hover:text-gray-700'
            }`}>
            {tabItem.label}
          </button>
        ))}
      </div>

      {/* Overview */}
      {section === 'overview' && (
        <div className="space-y-6">
          {/* Bio / Headline */}
          {(cpData?.headline || cpData?.bio) && (
            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5 space-y-2">
              {cpData?.headline && <p className="font-semibold text-gray-800">{cpData.headline}</p>}
              {cpData?.bio && <p className="text-sm text-gray-600 whitespace-pre-line">{cpData.bio}</p>}
            </div>
          )}

          {/* Key details grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Left: consultant details */}
            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5 space-y-4">
              <h3 className="font-semibold text-gray-900 text-sm">Profile Details</h3>
              <div className="space-y-3 text-sm">
                {cpData?.years_experience != null && (
                  <div className="flex justify-between">
                    <span className="text-gray-500">Experience</span>
                    <span className="font-medium text-gray-800">{cpData.years_experience} yrs</span>
                  </div>
                )}
                {cpData?.expertise_level && (
                  <div className="flex justify-between">
                    <span className="text-gray-500">Expertise</span>
                    <span className="font-medium text-gray-800 capitalize">{cpData.expertise_level.replace('_', ' ')}</span>
                  </div>
                )}
                {cpData?.hourly_rate != null && (
                  <div className="flex justify-between">
                    <span className="text-gray-500">Hourly Rate</span>
                    <span className="font-medium text-gray-800">${cpData.hourly_rate}/hr</span>
                  </div>
                )}
                {cpData?.availability_type && (
                  <div className="flex justify-between">
                    <span className="text-gray-500">Availability</span>
                    <span className="font-medium text-gray-800 capitalize">{cpData.availability_type.replace('_', ' ')}</span>
                  </div>
                )}
                {cpData?.travel_available != null && (
                  <div className="flex justify-between">
                    <span className="text-gray-500">Travel</span>
                    <span className="font-medium text-gray-800">{cpData.travel_available ? 'Available' : 'Not available'}</span>
                  </div>
                )}
                {cpData?.linkedin_url && (
                  <div className="flex justify-between items-center">
                    <span className="text-gray-500">LinkedIn</span>
                    <a href={cpData.linkedin_url} target="_blank" rel="noopener noreferrer"
                      className="text-blue-600 hover:underline text-xs truncate max-w-[160px]">
                      {cpData.linkedin_url.replace(/^https?:\/\/(www\.)?linkedin\.com\//, '')}
                    </a>
                  </div>
                )}
                <div className="flex justify-between border-t border-gray-100 pt-3">
                  <span className="text-gray-500">Cases Assigned</span>
                  <span className="font-bold text-blue-600">{assignedCount}</span>
                </div>
              </div>

              {/* Skills */}
              {cpData?.skills?.length > 0 && (
                <div className="border-t border-gray-100 pt-4 space-y-2">
                  <h4 className="text-xs font-semibold text-gray-400 uppercase tracking-wide">Skills</h4>
                  <div className="flex flex-wrap gap-1.5">
                    {cpData.skills.map((s, i) => (
                      <span key={i} className="px-2 py-0.5 bg-blue-50 text-blue-700 text-xs rounded-full">{s}</span>
                    ))}
                  </div>
                </div>
              )}

              {/* Avg rating by dimension */}
              {dimensions.length > 0 && (
                <div className="border-t border-gray-100 pt-4 space-y-2">
                  <h4 className="text-xs font-semibold text-gray-400 uppercase tracking-wide">
                    {t('profile.avg_rating')} {t('profile.by_dimension')}
                  </h4>
                  {dimensions.map(d => (
                    <div key={d.key} className="flex items-center justify-between text-sm">
                      <span className="text-gray-600">{d.label}</span>
                      <span className="font-semibold text-gray-800">{dimAvgs[d.key] ?? '—'}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Right: tier progress */}
            <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-5">
              <h3 className="font-semibold text-gray-900 text-sm mb-4">{t('profile.tier_progress')}</h3>
              <TierProgressBar
                ratingsData={ratingsData}
                currentTier={profileData?.trust_level}
                thresholds={thresholds}
              />
            </div>
          </div>
        </div>
      )}

      {/* Ratings history */}
      {section === 'ratings' && (
        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm">
          <div className="p-5 border-b border-gray-100 flex items-center justify-between">
            <h3 className="font-semibold text-gray-900">{t('profile.tab_ratings')}</h3>
            {overallAvg && (
              <span className="text-yellow-500 font-bold">★ {overallAvg} {t('profile.overall_avg')}</span>
            )}
          </div>
          {ratingsByCase.length === 0 ? (
            <div className="p-8 text-center text-gray-400 text-sm">{t('profile.no_ratings')}</div>
          ) : (
            <div className="divide-y divide-gray-50">
              {ratingsByCase.map(group => {
                const gAvgs = group.ratings.map(r => {
                  const vals = Object.values(r.scores ?? {});
                  return vals.length > 0 ? vals.reduce((s, v) => s + v, 0) / vals.length : 0;
                });
                const gAvg = gAvgs.length > 0
                  ? (gAvgs.reduce((s, v) => s + v, 0) / gAvgs.length).toFixed(2) : '—';
                return (
                  <div key={group.caseId} className="p-5">
                    <div className="flex items-center justify-between mb-3">
                      <span className="font-medium text-gray-800 text-sm">{group.caseTitle}</span>
                      <span className="text-xs text-yellow-600 font-semibold">★ {gAvg}</span>
                    </div>
                    {group.ratings.map(r => (
                      <div key={r.id} className="ml-3 border-l-2 border-gray-100 pl-3 mt-2 space-y-1.5">
                        <div className="text-xs text-gray-400">
                          {t('label.client')} · {new Date(r.created_at).toLocaleDateString()}
                        </div>
                        {dimensions.map(d => r.scores?.[d.key] != null && (
                          <div key={d.key} className="flex items-center justify-between text-xs">
                            <span className="text-gray-500">{d.label}</span>
                            <div className="flex gap-0.5">
                              {[1,2,3,4,5].map(s => (
                                <span key={s} className={s <= r.scores[d.key] ? 'text-yellow-400' : 'text-gray-200'}>★</span>
                              ))}
                            </div>
                          </div>
                        ))}
                      </div>
                    ))}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Tier progress */}
      {section === 'tier' && (
        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
          <h3 className="font-semibold text-gray-900 mb-5">{t('profile.tier_progress')}</h3>
          <TierProgressBar
            ratingsData={ratingsData}
            currentTier={profileData?.trust_level}
            thresholds={thresholds}
          />
        </div>
      )}

      {/* Activity */}
      {section === 'activity' && (
        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm">
          <div className="p-5 border-b border-gray-100">
            <h3 className="font-semibold text-gray-900">{t('profile.tab_activity')}</h3>
          </div>
          {activity.length === 0 ? (
            <div className="p-8 text-center text-gray-400 text-sm">{t('profile.no_activity')}</div>
          ) : (
            <div className="divide-y divide-gray-50">
              {activity.map(log => (
                <div key={log.id} className="p-4 flex items-start gap-3">
                  <div className="w-2 h-2 rounded-full bg-blue-400 mt-2 flex-shrink-0" />
                  <div className="min-w-0">
                    <div className="text-sm text-gray-700">{log.entity_name ?? log.event_type}</div>
                    <div className="text-xs text-gray-400 mt-0.5">{new Date(log.created_at).toLocaleString()}</div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Vouches */}
      {section === 'vouches' && (
        <div className="space-y-4">
          <VouchingPanel targetUserId={targetUserId} targetName={profileData?.full_name} />
        </div>
      )}

      {/* Edit profile */}
      {section === 'edit' && isOwnProfile && (
        <ProfileView auth={auth} compact={true} />
      )}
    </div>
  );
}

function NotificationBell({ auth }) {
  const { notifications, unreadCount, markRead, markAllRead } = useNotifications();
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    function handle(e) { if (ref.current && !ref.current.contains(e.target)) setOpen(false); }
    document.addEventListener('mousedown', handle);
    return () => document.removeEventListener('mousedown', handle);
  }, []);

  return (
    <div className="relative" ref={ref}>
      <button
        onClick={() => { setOpen(p => !p); }}
        className="relative p-2 rounded-xl text-blue-200 hover:bg-blue-900 transition-colors">
        <Bell size={20} />
        {unreadCount > 0 && (
          <span className="absolute -top-0.5 -right-0.5 min-w-[18px] h-[18px] bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center px-1 leading-none">
            {unreadCount > 99 ? '99+' : unreadCount}
          </span>
        )}
      </button>

      {open && (
        <div className="absolute left-0 bottom-full mb-2 w-80 bg-white rounded-2xl border border-gray-200 shadow-xl z-50 overflow-hidden">
          <div className="flex items-center justify-between px-4 py-3 border-b border-gray-100">
            <h3 className="font-semibold text-gray-900 text-sm">Notifications</h3>
            {unreadCount > 0 && (
              <button onClick={markAllRead} className="text-xs text-blue-600 hover:text-blue-700">
                Mark all read
              </button>
            )}
          </div>
          <div className="max-h-80 overflow-y-auto divide-y divide-gray-50">
            {notifications.length === 0 ? (
              <p className="py-8 text-center text-sm text-gray-400">No notifications yet</p>
            ) : notifications.map(n => (
              <div key={n.id}
                onClick={() => !n.is_read && markRead(n.id)}
                className={`px-4 py-3 cursor-pointer hover:bg-gray-50 transition-colors flex items-start gap-2.5 ${!n.is_read ? 'bg-blue-50/40' : ''}`}>
                {!n.is_read && <span className="mt-2 w-2 h-2 rounded-full bg-blue-500 shrink-0" />}
                <div className={!n.is_read ? '' : 'pl-4'}>
                  <p className="text-sm font-medium text-gray-800 leading-snug">{n.title}</p>
                  {n.body && <p className="text-xs text-gray-500 mt-0.5 leading-relaxed">{n.body}</p>}
                  <p className="text-xs text-gray-400 mt-1">{new Date(n.created_at).toLocaleString()}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

function EmptyState({ Icon: IconComp, title, subtitle, action }) {
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      <div className="mb-4 flex justify-center">
        {IconComp && <IconComp className="w-8 h-8 text-gray-300" />}
      </div>
      <h3 className="text-lg font-semibold text-gray-800 mb-1">{title}</h3>
      <p className="text-sm text-gray-500 mb-4">{subtitle}</p>
      {action}
    </div>
  );
}

function Modal({ open, onClose, title, children, wide = false }) {
  if (!open) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50">
      <div className={`bg-white rounded-2xl shadow-2xl w-full ${wide ? "max-w-3xl" : "max-w-lg"} max-h-[90vh] overflow-y-auto`}>
        <div className="flex items-center justify-between p-6 border-b border-gray-100">
          <h2 className="text-xl font-bold text-gray-900">{title}</h2>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600 text-2xl leading-none">&times;</button>
        </div>
        <div className="p-6">{children}</div>
      </div>
    </div>
  );
}

function Input({ label, ...props }) {
  return (
    <div className="mb-4">
      {label && <label className="block text-sm font-medium text-[#1C3557] mb-1">{label}</label>}
      <input
        className="w-full bg-gray-100 border-0 rounded-xl px-4 py-3 text-sm text-gray-800 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-400 shadow-sm"
        {...props}
      />
    </div>
  );
}

function Textarea({ label, ...props }) {
  return (
    <div className="mb-4">
      {label && <label className="block text-sm font-medium text-gray-700 mb-1">{label}</label>}
      <textarea
        rows={4}
        className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none"
        {...props}
      />
    </div>
  );
}

function Select({ label, options, ...props }) {
  return (
    <div className="mb-4">
      {label && <label className="block text-sm font-medium text-gray-700 mb-1">{label}</label>}
      <select
        className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white"
        {...props}
      >
        {options.map(o => (
          <option key={o.value} value={o.value}>{o.label}</option>
        ))}
      </select>
    </div>
  );
}

// ============================================================
// AUTH SCREEN
// ============================================================
function AuthScreen({ onAuth }) {
  const { t } = useT();
  const [mode, setMode]         = useState("signin");
  // Sign-in fields
  const [siEmail, setSiEmail]   = useState("");
  const [siPass,  setSiPass]    = useState("");
  // Sign-up wizard
  const [step, setStep]         = useState(0);
  const [email, setEmail]       = useState("");
  const [codeSent, setCodeSent] = useState(false);
  const [code, setCode]         = useState("");
  const [role, setRole]         = useState("");
  const [name, setName]         = useState("");
  const [password, setPass]     = useState("");
  const [confirmPass, setConf]  = useState("");
  // Consultant-specific
  const [headline, setHeadline]       = useState("");
  const [skills, setSkills]           = useState("");
  const [yearsExp, setYearsExp]       = useState("");
  const [hourlyRate, setHourly]       = useState("");
  const [expertiseLevel, setExpertise]= useState("mid");
  // Client-specific
  const [companyName, setCompany]     = useState("");
  const [industry, setIndustry]       = useState("");
  // Key-user detection (set after OTP verify)
  const [keyUserCompany, setKeyUserCompany] = useState(null);
  // Final-user detection (set after OTP verify, like key user)
  const [finalUserClient, setFinalUserClient] = useState(null); // { clientId, companyName } | null

  const [error, setError]   = useState("");
  const [loading, setLoad]  = useState(false);
  const auth = useAuth();
  const { settings: ssSettings } = useSystemSettings();
  const rolePermMatrix = ssSettings["role_permissions"] ?? {};
  function requiresTeamFor(role) {
    const defaults = ROLE_PERMISSIONS_DEFAULTS["require_team_signup"] ?? {};
    const stored   = rolePermMatrix["require_team_signup"] ?? {};
    return ({ ...defaults, ...stored })[role] === true;
  }

  const SIGNUP_STEPS = [
    { id: "verify",  label: t("auth.step_verify"),  Icon: Mail },
    { id: "role",    label: t("auth.step_role"),    Icon: User },
    { id: "profile", label: t("auth.step_profile"), Icon: FileText },
  ];

  function switchMode(m) { setMode(m); setError(""); setStep(0); setCodeSent(false); setCode(""); }

  // ── Sign in ──────────────────────────────────────────────────
  async function handleSignIn() {
    setError(""); setLoad(true);
    try { await auth.signIn(siEmail, siPass); onAuth(null); }
    catch (e) { setError(e.message); }
    setLoad(false);
  }

  // ── Step 0a: send OTP ─────────────────────────────────────────
  async function sendCode() {
    if (!email.trim()) { setError(t("auth.error_email_first")); return; }
    setError(""); setLoad(true);
    try {
      // signUp is the correct API for new account creation.
      // A random temp password is used here; the real password is set in Step 2.
      const tempPass = Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2).toUpperCase() + "1!";
      const { data, error: err } = await supabase.auth.signUp({
        email: email.trim(),
        password: tempPass,
      });
      if (err) {
        console.error("sendCode error:", err);
        // Extract a readable message — guard against Supabase returning "{}" as message
        const raw = err.message || err.error_description || err.msg || "";
        const isUseless = !raw || raw === "{}" || raw === "[object Object]";
        const msg = isUseless
          ? (err.status ? t("auth.error_status").replace("{n}", err.status) : t("auth.error_send_code"))
          : raw;
        if (msg.toLowerCase().includes("already registered") || msg.toLowerCase().includes("already exists"))
          setError(t("auth.error_email_taken"));
        else if (msg.toLowerCase().includes("rate limit") || msg.toLowerCase().includes("too many"))
          setError(t("auth.error_rate_limit"));
        else if (msg.toLowerCase().includes("signup") || msg.toLowerCase().includes("disabled"))
          setError(t("auth.error_signup_disabled"));
        else if (msg.toLowerCase().includes("smtp") || msg.toLowerCase().includes("email"))
          setError(t("auth.error_smtp"));
        else
          setError(msg);
      } else if (!data?.user || data.user.identities?.length === 0) {
        // Supabase returns an empty identities array when the email already exists
        setError(t("auth.error_email_taken"));
      } else {
        setCodeSent(true);
        setCode("");
      }
    } catch (e) {
      setError(e?.message || e?.toString() || t("auth.error_unexpected"));
    }
    setLoad(false);
  }

  // ── Step 0b: verify OTP ───────────────────────────────────────
  async function verifyCode() {
    if (code.length < 4) { setError(t("auth.error_verify_code")); return; }
    setError(""); setLoad(true);
    // type:'signup' matches the token sent by signUp
    const { data, error: err } = await supabase.auth.verifyOtp({
      email: email.trim(), token: code, type: "signup",
    });
    if (err) {
      setError(err.message || t("auth.error_invalid_code"));
      setLoad(false);
      return;
    }
    // Check if this user already completed their profile
    const { data: existing } = await supabase
      .from("users").select("role").eq("id", data.user?.id).maybeSingle();
    if (existing?.role) { onAuth(null); return; } // returning user → dashboard
    // Detect if this email is pre-registered as a key user on any case
    const { data: kuCases } = await supabase
      .from("cases")
      .select("key_user_email, client:client_id(client_profiles(company_name))")
      .eq("key_user_email", email.trim())
      .limit(1);
    if (kuCases?.length > 0) {
      const cp = kuCases[0].client?.client_profiles;
      setKeyUserCompany((Array.isArray(cp) ? cp[0]?.company_name : cp?.company_name) ?? "a company");
    } else {
      setKeyUserCompany(null);
    }
    // Detect if this email is pre-registered as a final user on any client team
    const { data: fuRows } = await supabase
      .from("client_team_members")
      .select("client_id, client:client_id(client_profiles(company_name))")
      .eq("email", email.trim())
      .limit(1);
    if (fuRows?.length > 0) {
      const cp = fuRows[0].client?.client_profiles;
      const companyName = (Array.isArray(cp) ? cp[0]?.company_name : cp?.company_name) ?? "a company";
      setFinalUserClient({ clientId: fuRows[0].client_id, companyName });
    } else {
      setFinalUserClient(null);
    }
    setStep(1);
    setLoad(false);
  }

  // ── Step 1: role chosen ───────────────────────────────────────
  function selectRole(r) { setRole(r); setError(""); setStep(2); }

  // ── Step 2: create account ────────────────────────────────────
  async function createAccount() {
    if (!name.trim()) { setError(t("auth.error_name")); return; }
    if (password.length < 6) { setError(t("auth.error_password_short")); return; }
    if (password !== confirmPass) { setError(t("auth.error_password_match")); return; }
    if (role === "consultant" && !headline.trim()) { setError(t("auth.error_headline")); return; }
    if (role === "client" && !companyName.trim()) { setError(t("auth.error_company")); return; }
    if (role === "key_user" && !keyUserCompany) { setError(t("auth.error_key_user")); return; }
    if (role === "final_user" && requiresTeamFor("final_user") && !finalUserClient) { setError(t("auth.error_team_code")); return; }
    if (role === "key_user"   && requiresTeamFor("key_user")   && !keyUserCompany)  { setError(t("auth.error_key_user"));  return; }
    setError(""); setLoad(true);
    try {
      await supabase.auth.updateUser({
        password,
        data: { full_name: name.trim(), role },
      });
      const { data: { user } } = await supabase.auth.getUser();
      await supabase.from("users").upsert(
        { id: user.id, email: user.email, full_name: name.trim(), role },
        { onConflict: "id" }
      );
      if (role === "consultant") {
        const skillsArr = skills.split(",").map(s => s.trim()).filter(Boolean);
        await supabase.from("consultant_profiles").upsert({
          id: user.id,
          headline: headline.trim(),
          skills: skillsArr,
          years_experience: yearsExp ? parseInt(yearsExp, 10) : null,
          hourly_rate: hourlyRate ? parseFloat(hourlyRate) : null,
          expertise_level: expertiseLevel,
        }, { onConflict: "id" });
      }
      if (role === "client") {
        await supabase.from("client_profiles").upsert({
          id: user.id,
          company_name: companyName.trim(),
          industry: industry || null,
        }, { onConflict: "id" });
      }
      if (role === "key_user") {
        // Link this user to all cases where their email was pre-registered as key user
        const { data: matchingCases } = await supabase.from("cases")
          .select("id").eq("key_user_email", user.email);
        if (matchingCases?.length) {
          await supabase.from("case_key_users").insert(
            matchingCases.map(c => ({ case_id: c.id, user_id: user.id }))
          ).onConflict("case_id,user_id").ignore();
        }
      }
      onAuth(role);
    } catch (e) { setError(e.message); }
    setLoad(false);
  }

  const logo = (
    <div className="text-center mb-8">
      <div className="inline-flex items-center justify-center mb-4">
        <img src={TECHCASE_LOGO_URI} width="256" height="256" alt="TechCase" style={{objectFit:"contain"}}/>
      </div>
      <h1 className="text-3xl font-bold text-[#1C3557]">TechCase</h1>
      <p className="text-blue-500 mt-1">{t("auth.tagline")}</p>
    </div>
  );

  const tabs = (
    <div className="flex rounded-xl bg-gray-100 p-1 mb-6">
      {[["signin", t("auth.sign_in_title")], ["signup", t("action.create_account")]].map(([m, label]) => (
        <button key={m} onClick={() => switchMode(m)}
          className={`flex-1 py-2 text-sm font-medium rounded-lg transition-all ${
            mode === m ? "bg-white shadow text-gray-900" : "text-gray-500 hover:text-gray-700"}`}>
          {label}
        </button>
      ))}
    </div>
  );

  const errorBox = error && (
    <div className="mt-4 p-3 bg-red-50 border border-red-200 rounded-xl text-sm text-red-700">{error}</div>
  );

  return (
    <div className="min-h-screen bg-[#D0E8F7] flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        {logo}

        {/* ── SIGN IN ── */}
        {mode === "signin" && (
          <div className="bg-white rounded-2xl shadow-xl p-8">
            {tabs}
            <Input label={t("auth.email")} type="email" value={siEmail}
              onChange={e => setSiEmail(e.target.value)} placeholder={t("auth.ph_email")} />
            <Input label={t("auth.password")} type="password" value={siPass}
              onChange={e => setSiPass(e.target.value)} placeholder={t("auth.ph_password_dots")} />
            {errorBox}
            <button onClick={handleSignIn} disabled={loading}
              className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 rounded-xl transition-colors disabled:opacity-50 mt-2">
              {loading ? t("auth.signing_in") : t("action.sign_in")}
            </button>
          </div>
        )}

        {/* ── SIGN UP WIZARD ── */}
        {mode === "signup" && (
          <div className="bg-white rounded-2xl shadow-xl p-8">
            {tabs}

            {/* Step progress */}
            <div className="flex items-center mb-8 relative">
              <div className="absolute top-4 left-4 right-4 h-0.5 bg-gray-200 z-0" />
              {SIGNUP_STEPS.map((s, i) => (
                <div key={s.id} className="relative z-10 flex flex-col items-center flex-1 gap-1.5">
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold ring-2 transition-all ${
                    i < step  ? "bg-emerald-500 text-white ring-emerald-100"
                    : i === step ? "bg-[#1C3557] text-white ring-blue-200"
                                 : "bg-gray-100 text-gray-400 ring-gray-200"}`}>
                    {i < step ? <Check size={11} /> : i + 1}
                  </div>
                  <span className={`text-xs font-medium ${i === step ? "text-[#1C3557]" : i < step ? "text-emerald-600" : "text-gray-400"}`}>
                    {s.label}
                  </span>
                </div>
              ))}
            </div>

            {/* Step 0 — Email verification */}
            {step === 0 && (
              <div>
                <h2 className="text-lg font-bold text-gray-900 mb-1">{t("auth.verify_heading")}</h2>
                <p className="text-sm text-gray-500 mb-5">{t("auth.verify_subtitle")}</p>
                <Input label={t("auth.email")} type="email" value={email}
                  onChange={e => setEmail(e.target.value)} placeholder={t("auth.ph_email")} />
                {!codeSent ? (
                  <button onClick={sendCode} disabled={loading}
                    className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 rounded-xl transition-colors disabled:opacity-50">
                    {loading ? t("auth.sending") : t("auth.send_code")}
                  </button>
                ) : (
                  <>
                    <div className="mb-4 p-3 bg-blue-50 border border-blue-100 rounded-xl text-sm text-blue-700">
                      <Mail className="w-4 h-4 inline-block mr-1" />{t("auth.code_sent").replace("{n}", email)}
                    </div>
                    <Input label={t("auth.code_label")} value={code}
                      onChange={e => setCode(e.target.value.replace(/\D/g, "").slice(0, 10))}
                      placeholder={t("auth.code_placeholder")} />
                    <div className="flex gap-2 mt-2">
                      <button onClick={sendCode} disabled={loading}
                        className="flex-1 border border-gray-200 text-gray-600 hover:bg-gray-50 font-medium py-2.5 rounded-xl text-sm transition-colors">
                        {t("action.resend")}
                      </button>
                      <button onClick={verifyCode} disabled={loading || code.length < 4}
                        className="flex-1 bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2.5 rounded-xl text-sm transition-colors disabled:opacity-50">
                        {loading ? t("auth.verifying") : t("auth.verify_btn")}
                      </button>
                    </div>
                  </>
                )}
              </div>
            )}

            {/* Step 1 — Role selection */}
            {step === 1 && (
              <div>
                <h2 className="text-lg font-bold text-gray-900 mb-1">{t("auth.what_brings")}</h2>
                <p className="text-sm text-gray-500 mb-5">{t("auth.choose_type")}</p>
                <div className="grid grid-cols-2 gap-3">
                  {[
                    { role: "consultant", Icon: Briefcase, label: t("auth.build_consultant"), desc: t("auth.help_clients") },
                    { role: "client",     Icon: Building2, label: t("auth.build_client"),     desc: t("auth.tell_consultants") },
                  ].map(opt => (
                    <button key={opt.role} onClick={() => selectRole(opt.role)}
                      className="flex flex-col items-center gap-2 p-5 border-2 border-gray-200 hover:border-blue-400 hover:bg-blue-50 rounded-2xl transition-all text-center group">
                      <opt.Icon className="w-8 h-8 text-blue-600 group-hover:text-blue-700" />
                      <span className="font-semibold text-gray-900 text-sm group-hover:text-blue-700">{opt.label}</span>
                      <span className="text-xs text-gray-500 leading-snug">{opt.desc}</span>
                    </button>
                  ))}
                </div>
                {/* Key User — locked by matrix or email pre-registration */}
                <button
                  onClick={() => (!requiresTeamFor("key_user") || keyUserCompany) && selectRole("key_user")}
                  disabled={requiresTeamFor("key_user") && !keyUserCompany}
                  className={`w-full mt-3 flex items-center gap-4 p-4 border-2 rounded-2xl transition-all text-left
                    ${(!requiresTeamFor("key_user") || keyUserCompany)
                      ? "border-blue-300 bg-blue-50 hover:border-blue-500 hover:bg-blue-100 cursor-pointer"
                      : "border-gray-200 bg-gray-50 opacity-50 cursor-not-allowed"}`}>
                  <UserCheck className={`w-8 h-8 flex-shrink-0 ${(!requiresTeamFor("key_user") || keyUserCompany) ? "text-blue-600" : "text-gray-400"}`} />
                  <div className="min-w-0">
                    <div className={`font-semibold text-sm ${(!requiresTeamFor("key_user") || keyUserCompany) ? "text-blue-700" : "text-gray-500"}`}>{t("auth.role_key_user")}</div>
                    <div className="text-xs text-gray-500 mt-0.5">{t("auth.key_user_desc")}</div>
                    {keyUserCompany
                      ? <div className="text-xs text-blue-600 font-semibold mt-1">{t("auth.key_user_linked").replace("{n}", keyUserCompany)}</div>
                      : requiresTeamFor("key_user")
                      ? <div className="text-xs text-amber-600 mt-1">{t("auth.key_user_not_registered")}</div>
                      : null
                    }
                  </div>
                </button>
                {/* Final User — only selectable if email is pre-registered on a client team */}
                <button
                  onClick={() => (!requiresTeamFor("final_user") || finalUserClient) && selectRole("final_user")}
                  disabled={requiresTeamFor("final_user") && !finalUserClient}
                  className={`w-full mt-3 flex items-center gap-4 p-4 border-2 rounded-2xl transition-all text-left
                    ${(!requiresTeamFor("final_user") || finalUserClient)
                      ? "border-teal-300 bg-teal-50 hover:border-teal-500 hover:bg-teal-100 cursor-pointer"
                      : "border-gray-200 bg-gray-50 opacity-50 cursor-not-allowed"}`}>
                  <Globe className={`w-8 h-8 flex-shrink-0 ${(!requiresTeamFor("final_user") || finalUserClient) ? "text-teal-600" : "text-gray-400"}`} />
                  <div className="min-w-0">
                    <div className={`font-semibold text-sm ${(!requiresTeamFor("final_user") || finalUserClient) ? "text-teal-700" : "text-gray-500"}`}>{t("auth.role_final_user")}</div>
                    <div className="text-xs text-gray-500 mt-0.5">{t("auth.final_user_desc")}</div>
                    {finalUserClient
                      ? <div className="text-xs text-teal-600 font-semibold mt-1">{t("auth.final_user_linked").replace("{n}", finalUserClient.companyName)}</div>
                      : requiresTeamFor("final_user")
                      ? <div className="text-xs text-amber-600 mt-1">{t("auth.final_user_not_registered")}</div>
                      : null
                    }
                  </div>
                </button>
              </div>
            )}

            {/* Step 2 — Profile details */}
            {step === 2 && (
              <div>
                <h2 className="text-lg font-bold text-gray-900 mb-1">
                  {role === "consultant" ? t("auth.build_consultant")
                    : role === "key_user" ? t("auth.build_key_user")
                    : role === "final_user" ? t("auth.role_final_user")
                    : t("auth.build_client")}
                </h2>
                <p className="text-sm text-gray-500 mb-5">
                  {role === "consultant"
                    ? t("auth.help_clients")
                    : role === "key_user"
                    ? t("auth.key_user_access").replace("{n}", keyUserCompany ?? "your company")
                    : role === "final_user"
                    ? t("auth.final_user_desc")
                    : t("auth.tell_consultants")}
                </p>
                {role === "key_user" && keyUserCompany && (
                  <div className="flex items-center gap-2 bg-blue-50 border border-blue-200 rounded-xl px-4 py-2.5 mb-4">
                    <Building2 className="w-4 h-4 text-blue-600 flex-shrink-0" />
                    <span className="text-sm text-blue-700 font-medium">{keyUserCompany}</span>
                  </div>
                )}
                {role === "final_user" && finalUserClient && (
                  <div className="flex items-center gap-2 bg-teal-50 border border-teal-200 rounded-xl px-4 py-2.5 mb-4">
                    <Building2 className="w-4 h-4 text-teal-600 flex-shrink-0" />
                    <span className="text-sm text-teal-700 font-medium">{finalUserClient.companyName}</span>
                  </div>
                )}

                {/* ── Common fields ── */}
                <Input label={t("label.full_name")} value={name}
                  onChange={e => setName(e.target.value)} placeholder={t("contact.ph_name")} />
                <Input label={t("auth.password")} type="password" value={password}
                  onChange={e => setPass(e.target.value)} placeholder={t("auth.ph_password")} />
                <Input label={t("auth.confirm_password")} type="password" value={confirmPass}
                  onChange={e => setConf(e.target.value)} placeholder={t("auth.ph_password_dots")} />

                {/* ── Consultant fields ── */}
                {role === "consultant" && (<>
                  <div className="border-t border-gray-100 my-4" />
                  <Input label={t("label.headline")} value={headline}
                    onChange={e => setHeadline(e.target.value)}
                    placeholder={t("auth.ph_headline_eg")} />
                  <Input label={t("profile.skills_label")} value={skills}
                    onChange={e => setSkills(e.target.value)}
                    placeholder={t("auth.ph_skills_eg")} />
                  <div className="grid grid-cols-2 gap-3">
                    <Input label={t("label.years_exp")} type="number" value={yearsExp}
                      onChange={e => setYearsExp(e.target.value)} placeholder={t("auth.ph_years_eg")} />
                    <Input label={t("label.hourly_rate")} type="number" value={hourlyRate}
                      onChange={e => setHourly(e.target.value)} placeholder={t("auth.ph_rate_num_eg")} />
                  </div>
                  <div className="mb-4">
                    <label className="block text-sm font-medium text-gray-700 mb-1">{t("label.expertise")}</label>
                    <select value={expertiseLevel} onChange={e => setExpertise(e.target.value)}
                      className="w-full border border-gray-300 rounded-xl px-3 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none">
                      <option value="junior">{t("level.junior")}</option>
                      <option value="mid">{t("level.mid")}</option>
                      <option value="senior">{t("level.senior")}</option>
                      <option value="expert">{t("level.expert")}</option>
                    </select>
                  </div>
                </>)}

                {/* ── Client fields ── */}
                {role === "client" && (<>
                  <div className="border-t border-gray-100 my-4" />
                  <Input label={t("company.name")} value={companyName}
                    onChange={e => setCompany(e.target.value)} placeholder={t("auth.ph_company_eg")} />
                  <div className="mb-4">
                    <label className="block text-sm font-medium text-gray-700 mb-1">{t("company.industry")}</label>
                    <select value={industry} onChange={e => setIndustry(e.target.value)}
                      className="w-full border border-gray-300 rounded-xl px-3 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none">
                      <option value="">{t("signup.select_industry")}</option>
                      <option value="technology">{t("industry.technology")}</option>
                      <option value="finance">{t("industry.finance")}</option>
                      <option value="healthcare">{t("industry.healthcare")}</option>
                      <option value="manufacturing">{t("industry.manufacturing")}</option>
                      <option value="retail">{t("industry.retail")}</option>
                      <option value="energy">{t("industry.energy")}</option>
                      <option value="logistics">{t("industry.logistics")}</option>
                      <option value="professional_services">{t("industry.professional")}</option>
                      <option value="other">{t("industry.other")}</option>
                    </select>
                  </div>
                </>)}

                <button onClick={createAccount} disabled={loading}
                  className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 rounded-xl transition-colors disabled:opacity-50 mt-2">
                  {loading ? t("auth.creating") : t("action.create_account")}
                </button>
                <button onClick={() => setStep(1)}
                  className="w-full mt-3 text-sm text-gray-400 hover:text-gray-600 transition-colors">
                  {t("action.back")}
                </button>
              </div>
            )}

            {errorBox}
          </div>
        )}
      </div>
    </div>
  );
}

